INSERT INTO `一一` VALUES (1,'根','推荐','“电影发明以后，人类的生命至少比以前延长了三倍”，当我觉得自己已经看了两个小时，一拉进度条发现才过了三十几分钟的时候，我深刻地理解到了这句话','2017-12-14 10:26:31'),(2,'彌張','无评分','真有这么好？我没看下去。。','2009-05-26 20:07:08'),(3,'眼角的花朵','力荐','婆婆，对不起，不是我不喜欢跟你讲话，只是我觉得我能跟你讲的你一定老早就知道了。不然，你就不会每次都叫我“听话”。就像他们都说你走了，你也没有告诉我你去了哪里，所以，我觉得，那一定是我们都知道的地方。婆婆，我不知道的事情太多了，所以，你知道我以后想做什么吗？我要去告诉别人他们不知道的事情，给别人看他们看不到的东西。我想，这样一定天天都很好玩。说不定，有一天，我会发现你到底去了哪里。到时候，我可不可以跟大家讲，找大家一起过来看你呢？婆婆，我好想你，尤其是我看到那个还没有名字的小表弟，就会想起，你常跟我说：你老','2008-06-29 12:20:53'),(4,'momo','推荐','如果电影都是过生活，那我们就过生活就好了','2009-01-02 18:01:36'),(5,'亵渎电影','力荐','我这样说好了，你不在的时候，我有个机会去过了一段年轻时候的日子，本来以为我再活一次的话也许会有什么不一样，结果还是差不多，没什么不同。只是突然间觉得，再活一次的话，好像真的没那个必要。真的没那个必要……★★★★★★','2009-07-21 00:36:10'),(6,'萨嘎摩多熊猫桑','力荐','从一个婚礼开始，到一个葬礼结束。','2009-02-17 21:09:18'),(7,'王小札','推荐','1.人们越长大就越看不到自己的后脑勺， 所以影片也选择性隐晦了故事的另一面: 洋洋湿漉漉笑着是被暗恋的女生救了， 胖子是被莉莉诱导杀害了自己的老师。 2.医生让全家人给病床上的婆婆多讲话， 妈妈哭着说她发现自己每天讲的都一样， 早上做什么，下午做什么，晚上做什么， 几分钟就讲完了，她觉得好像白活了。 3.儿女的情窦初开与父亲的初恋复燃， 用神奇的蒙太奇手法重合交织在一起。 4.雷电在亿万年无数次的击闪中， 诞生了一切生命的最基本单位氨基酸， 正如我们在无数的邂逅与接触中， 而在一瞬间大脑会爱上另外一个人。 某种意义上，两者都是在一刻发生的事。','2021-09-11 23:49:53'),(8,'大奇特(Grinch)','推荐','以一大家子来表现整个人生，从婚礼到葬礼，一切都是轮回。许多事物我们只能看到它的一半，另外一半需要别人帮我们发现。','2009-02-06 00:38:15'),(9,'水湄物语','力荐','年轻的人无法解读的一种电影','2005-11-27 17:16:32'),(10,'kingfish','推荐','看似平淡无奇,其实蕴含深意','2006-03-22 13:41:59'),(11,'影志','力荐','“自从电影发明以后，人类的生命就至少延长了三倍” “本来以为，我再活一次的话，也许会有什么不一样。结果还是差不多，没什么不同。只是突然觉得，再活一次的话，好像，真的没那个必要。” “你自己看不到，所以我拍给你看。” “没有一朵云，没有一棵树，是不美丽的。” “我觉得，我也老了…”','2014-07-04 11:19:48'),(12,'巴喆','力荐','《一一》被法国媒体形容为“生命的诗篇”，透过电影传颂吟唱，在叙述一则简单的家庭故事时，真正触摸到“情感的精髓”，以四两拨千金的娴熟技巧交待了少女心事、童年困惑、事业危机、家庭纠纷，以及对宗教的慨叹和对时事的讽刺。9.7','2012-02-17 17:57:02'),(13,'晚安小姐','力荐','我看到了一生','2006-04-08 09:46:35'),(14,'微挺','力荐','你知道的太多了 其实 杨德昌很像小波，那么的冷静和尖锐，你看完以后永远不记得他说了什么故事，却一直记得他的句子。','2008-12-23 19:24:20'),(15,'Henry','力荐','用三小时去看懂人生，看不懂，活下去就会懂','2012-08-23 11:23:41');
/*!40000 ALTER TABLE `一一` ENABLE KEYS */;
UNLOCK TABLES;

