--
-- Dumping data for table `上帝之城`
--

LOCK TABLES `上帝之城` WRITE;
/*!40000 ALTER TABLE `上帝之城` DISABLE KEYS */;
INSERT INTO `上帝之城` VALUES (1,'[己注销]','推荐','（8/10）影片最后杀死主角的那群熊孩子的演员，此后他们真的成了黑社会………………………………………………………………………','2013-11-01 23:55:28'),(2,'同志亦凡人中文站','推荐','不只枪支，摄影也可以改变命运。血腥暴力、丛林法则以及完全不会出现在明信片上的里约。剪辑酣畅淋漓得像桑巴舞曲。据说奥运期间巴西政府对贫民窟的做法是建堵高墙眼不见为净，我...','2016-08-05 04:09:27'),(3,'润物','推荐','一部震撼人心的电影。是的，这部电影带给人的冲击力之大难以用语言来形容，首先导演的水平很高，拍摄手法和剪辑方式都相当前卫，配乐也是和主题形成了巨大的反差效果，故事越是残酷音乐越是奔放，里约热内卢的贫民窟，世界上最接近地狱的地方，电影真实地还原了那里发生的一切，从孩子开始，无法无天。','2013-10-11 00:53:27'),(4,'砚小朵™','推荐','我现在看啥都是鸡汤。在这种荒诞、粗砺的虎狼之地中过活，结果活的生机勃勃自得其乐，旺盛的生命力，天生的钝感力，皮糙肉厚，从不忧郁。','2016-08-21 23:11:53'),(5,'September','力荐','脸盲症发作，愣是20分钟才把人脸分清。','2010-12-15 21:05:49'),(6,'老鸡｜扶立','力荐','看过巴西，才知道我国多么安定……','2008-01-10 17:16:05'),(7,'战国客','力荐','史上最强剪辑，《低俗小说》遇上它也要甘拜下风！第一次接触巴西电影，就让我着实惊叹了一大下~~','2007-06-24 10:36:24'),(8,'Bigteeth','力荐','评论这部电影是可耻的','2007-08-26 22:41:52'),(9,'A-sun*','推荐','这配乐这镜头！！！！','2010-07-01 20:44:20'),(10,'欢乐分裂','推荐','4.5；视听太炫技了——长镜穿过被主遗忘的贫民窟，手持寓意的混乱无序动荡（用得如此贴合），分屏中的剧情浓度，华丽剪辑居功至伟（高效剪出一个体量极大的关系网，其高速感与整体基调极为契合，堪称模板剪辑），配乐简直分分钟都击到心尖（班尼欢送会那段看得目瞪口呆，灯光穿过乐声在死亡降临处静止，绝妙的处理啊），多线叙事的交织出厚重文本（叙事闭合成就完满）。 看这样一部片很难不满足，几乎癫狂的暴力中竟还掺有黑色幽默的成分，细思全是悚然；一个笼罩在冤冤相报罪行怪圈中的无主之地，众线交叠的正是曾怀有良知微光的普通人如何踏入残酷火并，懵懂孩童如何以枪杀毒品标榜男性雄风；结尾更是惊心——小霸王倒下，然而会有更多造反后浪雨后春笋，cue到某卫/bing吓一跳。','2021-05-17 11:34:29'),(11,'城南草木生','力荐','可是我们的困难无关紧要，在里约热内卢的风景明信片上，是不可能看到我们的','2009-11-10 17:29:12'),(12,'LORENZO 洛伦佐','推荐','暴力枪战、高速剪辑、晃镜、多画面以及各种无序感。看来很震撼的一部电影，故事讲述的方式颇具传奇色彩。巴西荣升心目中民风彪悍第一圣地。','2011-04-22 04:09:34'),(13,'Q。','力荐','“被上帝抛弃了的上帝之城”一个除了偷窃，强奸、走私、贩毒、杀人、抢劫无处不在的城市，因为这里无需偷窃，而犯罪的几乎都是未成年的孩子，这里是真正的地狱和人性泯灭的地方。高超的剪辑、丰富的剧情、合适的配乐组成一部十分优秀的影片，更加让人震撼的是这部影片是根据真实故事改编。★★★★★','2010-12-08 20:59:19'),(14,'阿朽','力荐','离暴力最近的人，离天堂最近。','2008-02-01 15:24:52'),(15,'海心','推荐','真暴力，真真实，真残忍，真可悲。','2009-04-03 20:58:13');
/*!40000 ALTER TABLE `上帝之城` ENABLE KEYS */;
UNLOCK TABLES;

