INSERT INTO `乱世佳人` VALUES (1,'海心','力荐','请上帝保佑那个真正爱你的人吧，你把他的心都揉碎了。','2008-01-17 07:36:57'),(2,'寂地','力荐','一定要看啊,我喜欢斯加丽那种几乎有点蛮横的可爱感觉.甚至可以为了达到目的不责手段,要么爱她,要么讨厌她.她在贫瘠的大地上拿着一根萝卜说(这个,好象很搞笑)\"我对上帝发誓,我再也不要挨饿!\"我爱上她了!','2006-01-03 17:44:58'),(3,'沈书君','推荐','也许每个女孩子心中都有一个艾希礼，只有经过时光才发现真爱原来是班瑞德。','2008-10-06 09:38:02'),(4,'影志','力荐','Tomorrow is another day. 又一句该死的经典台词。','2005-08-24 07:21:29'),(5,'funny_vee','力荐','那么早期的电影居然到现在也看不出瑕疵，太崇拜那个导演了。','2006-11-28 17:15:22'),(6,'沉歌','推荐','至今记得亚特兰大的战火中她奔走的背影，裙裾摆动。她的野性和骄傲，坚强与倔强，不甘弱示或屈服，瑞德与她是相似的。如果瑞德爱上的不是郝思嘉，一定不会掉进那个自掘的陷阱里。对于郝思嘉佩服之极，对于瑞德，感动了，且唏嘘而惋惜。','2008-03-03 11:20:49'),(7,'小霸王','力荐','看完斯嘉丽那么瘦小的身躯，却承受着那么大的压力，都能顶的住。真的感觉不到什么叫困难了，第二天去考试奇迹般的过了。。','2012-10-27 00:20:28'),(8,'小海','无评分','这部电影的北美票房计入通货膨胀影响之后的数据是十六亿美元，今天北美电影过四亿都惊天地泣鬼神了，跟爷爷辈比起来还是too young 啊……','2012-05-20 18:54:21'),(9,'小爱','力荐','Clark Gable你真是每一个女人都会梦想得到的男人','2010-04-02 00:14:18'),(10,'刷鞋大王','还行','绿茶婊上位的奋斗史～看到一半大跌眼镜，名著果然不按套路出牌，经历了战争和贫穷的洗礼后，女主变得更婊、更冷血、也更丧心病狂了。所谓的自强和韧性，不过是中产阶级精致的利己主义罢了。啊好讨厌这个把马儿累坏又活活鞭打而死的坏女人！！！你才是个该死的畜生！！结尾真是大快人心，“你受的罪都是你自找的，如果有天理的话你应该受更多罪”为India这句话怒点一百个赞！','2020-06-12 01:11:41'),(11,'呵哈呼嘻嗨嘿嘤','力荐','郝思佳不算是个“好女人”，但她身上有着或许很多男人都没有的韧性，仿佛什么都无法打倒她，她永远能找到支点，重新站起来，正如她一直记在心里的“tomorrow is another day”。','2016-12-02 20:01:37'),(12,'艾小柯','力荐','永远的经典，永不被打倒的勇气。','2006-06-16 03:16:04'),(13,'朝暮雪','推荐','原来80年前斯嘉丽就当了黑寡妇。','2017-03-15 02:49:32'),(14,'同志亦凡人中文站','力荐','乱世只是背景，更多是跌宕起伏的女性画卷。费雯丽塑造了大银幕上绝无仅有的佳人形象：斯嘉丽任性而深情、虚荣而善良、软弱而坚强，爱得情天恨海而又愚蠢天真......在电影院如痴如醉的坐了4个小时~~~','2018-05-13 15:44:44'),(15,'货拉拉拉布拉多','力荐','将近４个钟头却还是让人意犹未尽．淋漓尽致了～','2008-06-10 21:54:30');
/*!40000 ALTER TABLE `乱世佳人` ENABLE KEYS */;
UNLOCK TABLES;

