LOCK TABLES `你的名字_` WRITE;
/*!40000 ALTER TABLE `你的名字_` DISABLE KEYS */;
INSERT INTO `你的名字_` VALUES (1,'CharlesChou','还行','和《追逐繁星的孩子》同个毛病——一个平时专注于言情的人看了科幻小说之后可能就是这样的，他执着于用新学到的概念来包装自己的认知，而不是放手让这个概念去革新它。','2016-09-08 22:25:45'),(2,'同志亦凡人中文站','推荐','新海诚终于会讲一个复杂故事了，真不容易啊！当年那部搔首弄姿、无病呻吟的“言叶之庭”差点让我转成终身黑，“君之名”却轰出了我睽违已久的少女心。彗星降临的末世情怀，穿越时空的灵之绳结，只有7秒钟记忆的鱼...星空、爱情以及所有遇见都是注定。','2016-09-08 08:06:11'),(3,'银河系漫游指南','力荐','这部片深刻地告诉我们 一个有好剧本的诚哥有多可怕 ☄','2016-09-05 21:17:35'),(4,'华盛顿樱桃树','还行','到底该在哪里哭？？！！很悲哀，我已铁石心肠：）','2016-11-21 22:41:39'),(5,'哪吒男','推荐','你我相逢在黑夜的空中，你有你的我有我的方向，你记得也好，最好你忘掉，在这交会时互放的光亮。','2016-09-08 17:48:31'),(6,'邓安庆','推荐','一清早醒来捏捏自己的胸部，“啊，真不好意思呢。”然后穿上了人家的裙子，美满地过了女生的一天。','2016-12-04 15:39:08'),(7,'紫苏バジル','推荐','聚结成状，交错纠缠，时而回转，中断，却又再次续接。这就是组纽。这就是时间。这就是结。黄昏，不是白昼亦不是夜晚，是我努力却看不清你的脸。たそがれ、誰そ彼。我已记不得你的名字，却还记得喜欢你。','2016-09-03 19:58:35'),(8,'小鱼问题不大','力荐','黛玉心中想道：“好生奇怪，倒像在哪里见过一般，何等眼熟到如此!” 宝玉看罢，因笑道：“这个妹妹我曾见过的。” 贾母笑道：“可又是胡说，你又何曾见过他？” 宝玉笑道：“虽然未曾见过他，然我看着面善，心里就算是旧相识，今日只作远别重逢，未为不可。”','2016-10-03 08:37:02'),(9,'柏林苍穹下','推荐','斗转星移，蓦然回首，那人却在，灯火阑珊处。','2016-09-10 19:28:50'),(10,'翻滚吧！蛋堡','力荐','新海诚用这样的故事去温暖城市中每一个仍然愿意相信爱的人。在这么大的世界里，能够遇见你，竟然需要如此用力。穿越错位的时空，仰望陨落的星辰，你没留下你的名字，我却无法忘记那句“我爱你”。','2016-09-07 12:13:58'),(11,'库索','力荐','这一次要给新海诚打200分，在我鄙视他不过只是纯情小清新的10年前，没料到有朝一日会在电影院里哭到断气。恍惚看到了穿越时空少女时期的细田守。为所有的少女心和中二病鼓掌，青春不死就能相遇，就能拯救地球。现在我抹着眼泪走出影厅，看到后排的少年摘下眼镜，嚎啕大哭起来。。。','2016-08-27 18:55:23'),(12,'空気嫁','力荐','错过和努力才是爱和青春的墓志铭','2016-08-28 15:57:13'),(13,'有心打扰','力荐','只有新海诚才能让我一次又一次感受到爱情的纯粹与美好。被爱情伤得遍体鳞伤的我，不再相信爱情的我，突然会想，不如再勇敢地去谈一场恋爱？嗯，好像可以！','2016-09-07 15:28:51'),(14,'隆咚锵','力荐','先写下 我爱你 再到世界尽头找你的名字','2016-09-09 01:39:10'),(15,'xxhhcc','推荐','整体还是略矫情，同样是换身体的青春映画没有大林宣彦的<转校生>克制。不过新海诚故事能力确实有进步，或许如他所说的那样得到了川村元气的帮助。这片票房的成功或将彻底改变后宫崎骏时代日本动画电影市场的格局。电影3星+产业影响力1星。感叹细田守<穿越时空的少女>晚公映10年会是什么状况','2016-09-20 18:58:01');
/*!40000 ALTER TABLE `你的名字_` ENABLE KEYS */;
UNLOCK TABLES;

