INSERT INTO `借东西的小人阿莉埃蒂` VALUES (1,'小锡兵','力荐','此生暂借于世上。。这是无言的结局，我能想见阿莉艾蒂最终被同族淳朴少年打动，相守繁衍。那个有温柔眼眸的人，从此相忘天涯，深藏于心。','2011-06-20 01:40:22'),(2,'岛上的夏奈','力荐','能赠予你的临别礼物，不过是一块小小的方糖。','2011-06-18 03:04:18'),(3,'Q。','推荐','“你永远在我心中，我永远都不会忘记你。”这是一部难得一见的富含诗意和伤感的动画片。细节和人设很棒，赏心悦目；配乐尤其出色，但叙事太过苍白匆忙。最后的轻轻告别，两人往后都会有自己人生，走自己的路，但曾经那段美好依旧会沉淀为一辈子的记忆。★★★★','2011-06-24 10:49:32'),(4,'Miya.','推荐','我相信他们终有一天还会遇见的。','2011-06-17 18:57:54'),(5,'病気君','推荐','那个该死的女佣怎么不去吃屎啊！！！！！！！！！','2011-06-30 22:54:49'),(6,'根','力荐','阿春那种无缘无故的残忍和仇恨是怎么来的呢？不过想想我小时候也爱水淹蚂蚁什么的，大概是同一种心理吧。','2012-08-05 13:16:32'),(7,'称称','推荐','宫崎骏爷爷是要告诉我们，即便你爱着城堡少爷，你最后也只能嫁给隔壁张三。','2012-04-15 13:02:15'),(8,'shiya','力荐','比波妞好看多了……而且配乐相当好听……','2010-07-21 23:14:53'),(9,'阿翮','力荐','吉卜力的动画里，总有个坚强的姑娘。最后送别时阿莉埃蒂摘下发卡，栗色的头发飘起来，她把它送给翔，说把它带在身边，翔微微睁大眼睛。我就是在这个时候，掉下了眼泪。阿莉埃蒂也掉下眼泪。一年多以来几乎没有什么戳中我泪点的电影。少女说“你保护了我，很开心。”而少年只是轻声呼唤着少女的名字。','2011-06-18 23:49:52'),(10,'迦拉夏','力荐','刚去看了回来，音乐实在太赞了！','2010-07-17 21:23:00'),(11,'五色全味','推荐','“我們要努力活下去！”但願你不要隨便放棄','2011-01-02 23:42:18'),(12,'17950','推荐','雖然很吉卜力，但其實和宮崎駿本人的戲劇風格很不同，沒有明顯的起承轉合，主題也不深入，但是很平靜。。。 也許米林宏昌的個人風格還沒有完全顯現出來呢。','2010-12-25 22:11:31'),(13,'BabyMoon','力荐','香港首映宫崎峻的借东西的小女孩亚利亚蒂。刚看完出来。观众在亮灯时仍然没人起身，一直到字幕结束。非常唯美，非常感人。我要去下ost。电影给六颗星。','2010-12-25 23:20:32'),(14,'工凡','推荐','人类的自大太可怖了，不只是春无来由的恶意可怖，翔粗暴地将定制厨房塞进阿莉埃蒂的家也是一样。阿莉埃蒂的强大在于，不惧信任也不惧对话。','2022-05-26 22:15:08'),(15,'诺顿家的花儿','力荐','她在他的手心，她在他的肩头，她在他的心间。感谢宫崎骏，感谢吉卜力，总是给我们纤尘不染的梦。','2011-06-22 16:48:54');
/*!40000 ALTER TABLE `借东西的小人阿莉埃蒂` ENABLE KEYS */;
UNLOCK TABLES;

