INSERT INTO `功夫` VALUES (1,'Bono','力荐','超级耐看和严重被低估的电影，看十来遍了越看越好看，我想100年后还是有很多人爱看它。','2012-07-24 23:20:59'),(2,'芥末小馒头','推荐','不要说烂，其实很卡通很cult','2007-02-15 18:38:00'),(3,'鱼丸粗面','推荐','华丽的夸张，情节倒是紧凑，毫不拖沓','2006-07-17 11:33:37'),(4,'郁程','力荐','再都不可能出现比它牛B的功夫电影了','2009-09-05 08:24:31'),(5,'离','推荐','电影院里他说，你笑得好开心。','2008-11-20 21:24:37'),(6,'魚山飯寬','力荐','重温星爷的功夫，猛觉得这是部无比伟大的电影！','2012-01-29 02:19:06'),(7,'谋杀游戏机','推荐','在香港影史上应有特殊地位，拓展了武侠片的类型时空。草根无厘头，想象与反讽、结构与解构融为一体。数字技术创造的实景奇观','2012-11-20 23:24:11'),(8,'杜边生','无评分','如来神掌从此和竹蜻蜓有了联系','2007-11-17 05:20:34'),(9,'同志亦凡人中文站','推荐','这是周星驰最后一次让我感到可爱...','2012-06-16 15:22:24'),(10,'一夏秋凉','力荐','别装逼了，这片绝对值5星','2016-06-12 13:40:55'),(11,'你在百花深处','推荐','黄圣依的哑女可真美，真纯，电影还是星爷一贯的小人物到大英雄，很经典，很有意义','2018-03-14 11:30:35'),(12,'欢乐分裂','推荐','重看四星半，毕竟当年不识其中味；快银前身，阿Q后裔，大时代里的小人物，小世界里的大境界；每个华语导演都有一个武侠梦，每个男孩都有一个英雄梦，每个孩子都有一个甜蜜梦想；开场就高潮，武打段落章节分明，门派清楚，人外有人，仁者无敌；最爱星爷嬉笑之余的严肃，热闹之外的荒凉。','2015-01-15 15:24:16'),(13,'橘猫爱吃鱼','推荐','不再是星爷的个人秀，而是群英共舞。包租公、包租婆、苦力强、裁缝、油炸鬼等角色都鲜活独特，过目难忘！','2018-05-02 12:44:18'),(14,'kingfish','力荐','包租公,包租婆,斧头帮,冯小刚被砍,....都是经典.','2006-03-22 12:49:37'),(15,'时间的玫瑰','还行','不喜欢什么高科技，越来越不真诚。','2008-03-25 14:33:40');
/*!40000 ALTER TABLE `功夫` ENABLE KEYS */;
UNLOCK TABLES;

