INSERT INTO `千钧一发` VALUES (1,'根','推荐','长伊桑霍克这样的被认为是基因差……','2017-06-09 14:40:48'),(2,'半袖','力荐','没有触目惊心的科幻大场面，娓娓的说伦理、说基因技术的双刃剑。让我落泪的点不是主角们，而是最后那个医生，原来他一直都在帮助Vincent，这种梦想一旦被共享，也就推动了第一块多米诺骨牌。有趣的是，片名本身是由DNA的碱基组成的，片尾字幕显示剧组成员名字时也是先凸显出G.A.C.T，很有心思的小细节。','2008-02-24 16:32:47'),(3,'蜉蝣','较差','尽管格局已经这么小了，依然漏洞百出。科幻外衣包裹下的无聊案情。','2018-07-04 14:42:31'),(4,'荔枝超人','推荐','“我只是把身体给了你，你却让我分享了你的梦想”（Nyman先生的配乐太惊艳','2008-07-27 16:04:13'),(5,'同志亦凡人中文站','力荐','人类的历史就是一部歧视史，财富、地位、年龄、性向、肤色...基因决定人生，不过是把这种歧视从人的出生开始以科学的形式固定下来。电影想讲述的是：我也许没有伟大的基因，但我有一颗造梦的心——我就是那个统计学上渺小到不计、但没人可以抹去的1%。','2013-02-02 20:45:00'),(6,'Doublebitch','力荐','当你有梦想 全世界都会帮你','2010-08-01 19:43:57'),(7,'丁小云','力荐','看了这部《千钧一发》，没想到还真不错，男煮饺儿追求梦想时不给自己留任何后路的精神真鸡巴励志啊……这种励志非心灵鸡汤式励志，而是心灵牛鞭汤式励志……我们曾经都是星尘，莫名其妙地来到了父亲的睾丸里，来人世走一遭后重新变成星尘……反正迟早变星尘，不如追梦尽情活……','2012-04-11 21:55:30'),(8,'私享史','推荐','问题不在于基因，也不在于决定论，而在于一种万恶的标准和秩序，试图消灭美妙的多样性。','2012-04-07 23:59:38'),(9,'撒旦的表妹','力荐','看名字以为是恐怖片，没想到是这么走心的风格。裘德洛的出场太惊艳了，那双眼睛，那个孤傲的眼神和表情让人难忘。可他最后结束自己生命的方式太残忍了，难以接受。','2012-04-07 23:01:50'),(10,'阿子','推荐','现在再看，还挺腐的。。。','2010-05-27 21:16:51'),(11,'巽','推荐','这名字译得太搞了～＝＝','2007-12-25 13:43:07'),(12,'川总','力荐','古怪的老电影气质，很励志，有点基。世界若是真的如此不公平，那我们就集体作弊去吧。','2012-03-10 12:44:47'),(13,'黄青蕉','力荐','科幻版天才雷普利','2011-12-21 23:55:51'),(14,'spencer','力荐','梦想与扼杀梦想的不公平，过去、现在还是未来，这是人类戏剧的永恒主题之一。','2010-10-02 01:13:41'),(15,'无效设备','力荐','2018年11月26日，人民网的新闻宣称，世界首例免疫艾滋病的基因编辑婴儿在中国诞生。 《千钧一发》里最令人动容的是，Vincent作为未来世界里的\"瑕疵人\"，绝不回头，绝不留后路的追梦历程，既然是浩瀚宇宙中微如星尘般的存在，又何惧以星尘的模样\"归家\" ，在人世间放手一搏尽兴地活是Vincent的选择，也是影片除基因重组，人伦道德等探讨点，传达给观众的更重要的生命意义。 但结合今天的新闻来看，片中对基因技术，人类伦理的平铺直叙，令人背脊发凉，正如《黑镜》里所说“我从没想过自己会活在未来，但我现在TM就在未来。”','2018-11-27 04:01:22');
/*!40000 ALTER TABLE `千钧一发` ENABLE KEYS */;
UNLOCK TABLES;

