/*!40000 ALTER TABLE `哈利_波特与凤凰社` DISABLE KEYS */;
INSERT INTO `哈利_波特与凤凰社` VALUES (1,'A-sun*','还行','感觉好奇怪啊，正常来说看一部电影应该觉得自己和主人公的命运绑在一起，但这里完全不觉得对波特有任何同情，就对他所作的任何一个决定都认为是活该都想骂他，这到底是哪里出了问题，真是觉得好奇怪啊!','2011-06-21 02:12:51'),(2,'无语望天','推荐','给小天狼星','2016-12-12 23:42:25'),(3,'摇曳萧萧下','推荐','秋张同学迷人的样子教我忍不住吐了好多回。于谦儿才不是包子脸，你才是你才是。','2010-06-01 04:23:28'),(4,'国王KING','力荐','和奶奶在影院看的第一部，也是最后一部电影。虽然奶奶看不懂，但还是认认真真地陪我看完了，散场后说“如果你表姐也在就好了，她会喜欢的”。07年夏天暑假在广州一个小电影院的回忆，无比怀念。我和哈利一样，都失去了最亲的人。奶奶，希望远方的您，一切安好。','2009-08-11 23:32:24'),(5,'同志亦凡人中文站','还行','只有露娜是亮点','2012-07-20 19:52:06'),(6,'Tari','力荐','在b站看时，小天狼星死的时候，有一条弹幕大概是说，这是哈利第二次知道原来一条咒语就可以夺走一个人的性命，第一次是学长，现在是教父。真是感慨。 魔法部来的老女人实在是招人讨厌，不过想想也算是对当下教育现状的一种讽刺吧，很多年过去了，这段仍然可以拿出来针砭时弊。','2020-12-19 21:48:18'),(7,'汝就做吾的犬吧','推荐','这部看得还是比较开心的，情节展开得很紧凑，一开始就直奔主题了，食死徒和凤凰社打得也比较精彩，伏地魔和邓布利多那场也很华丽，还有双胞胎让应试教育吃瘪那段也很过瘾。要说不满意的话有一点倒是真不大满意：那个中国姑娘长得实在是…','2011-08-07 23:21:18'),(8,'齐木楠雄','推荐','后面3集比前4集差一点','2016-10-21 15:28:03'),(9,'给我个电话亭，我要拯救地球！','推荐','之前一直不敢看呢真是…闪光点都是龙套 跟着英国最好的演员演了这么多年戏还一点长进没有的猪脚真是令人拙计','2012-07-24 09:56:57'),(10,'♣lùlu♣','力荐','其实我不记得我看过没','2007-06-29 12:31:44'),(11,'冰山李','推荐','6.7；牺牲原著至少换得了情节紧凑','2010-05-10 20:53:10'),(12,'Mr.Cookie?','力荐','乌姆里奇的形象塑造的很好，即使在剧中是个反派。粉红色的突兀鲜亮风格行走在黑色绅士低调画风的城堡里显得尤为突兀，与她的处处挑刺相呼应。另外她办公室里非常众多的可爱猫咪、喝咖啡加两勺糖、总是似笑非笑的狰狞表情以及纯粉的办公室风格等细节都与她的刻薄歹毒的特点形成强烈反差，戏剧性很强也很滑稽。','2021-09-29 12:25:47'),(13,'临素光','推荐','我最大的怨念就是哈利没跟卢娜在一起，整个系列他们两人的全部对手戏都超级带感，既有浪漫又有火花，还对情节有关键的推进作用。反观哈利跟金妮，完全不知道怎么搭上的，强行尬演，让这个系列原本就不怎么好看的感情戏雪上加霜。','2020-03-08 10:34:58'),(14,'?️','力荐','在教室点燃的反叛的烟花，抵制入侵时闪回的每个关于爱和友情的瞬间，都熠熠生辉。','2022-08-19 21:21:14'),(15,'Hyde','力荐','奠定我价值观的一部作品，最爱电影最后一幕双胞胎冲出来撒糖果，去他吗的伏地魔，去他吗的食尸徒，我为我的信念而战。','2022-03-28 15:55:47');
/*!40000 ALTER TABLE `哈利_波特与凤凰社` ENABLE KEYS */;
