INSERT INTO `哈利_波特与密室` VALUES (1,'Nakedself','力荐','再没有什么比一封吼叫信更叫人晕菜了！','2006-05-17 15:59:27'),(2,'Kreuzberg','推荐','最最最欢乐的一刻是当邓布利多宣布取消考试、全部学生都高兴地拍掌的时候，赫敏幽怨地说了一句：No~。','2011-08-11 14:35:14'),(3,'约翰迈克莱恩','推荐','邓布利多那句：“让我们成为哪种人的并不是我们的能力，而是我们的选择。”重温发现这句话简直是哈利波特的点睛总结。','2019-03-10 19:37:29'),(4,'Sophie Z','力荐','邓布利多说：让我们成为哪种人的并不是我们的能力，而是我们的选择。','2010-11-24 16:46:46'),(5,'熊✌?','力荐','那时候看电影才9块钱！','2012-03-24 13:28:58'),(6,'张苑希','推荐','“让我们成为哪种人不是因为我们的能力，而是因为我们的选择”。即使是在魔法世界里，阶级、出身、血统的歧视差别也是无处不在的，不过作为儿童文学其中表达的情感基调还是很正面的。青年伏地魔甚是亮眼，主角三人团也很有爱。','2017-11-26 19:00:51'),(7,'同志亦凡人中文站','力荐','如果一直能由哥伦布导演，那哈迷该多幸福啊...','2012-07-20 19:54:41'),(8,'木由','力荐','重温有个好处，就是能发现很多从前没注意到的小细节。例如金妮见到哈利一声尖叫，例如弱鸡的罗恩二话不说掏出魔法棒攻击对赫敏出言不逊的马尔福，例如哭泣的桃金娘的回忆。坏处就是以现在的眼光看总觉得伏地魔输得憋屈，最后的决斗也打得像过家家。','2018-08-07 06:07:59'),(9,'根','推荐','相比于小说中哈利很干净利落地干掉了大蛇，电影里这一场仗可干得很长。','2012-01-12 13:49:18'),(10,'Chris','推荐','\"It is not our abilities that show what we truly are,it is our choices.\"?（ps：Dobby好可爱～?）','2017-05-03 22:14:01'),(11,'友邻广播','力荐','snape越看越可爱。这部好多梗哈哈。','2011-05-28 00:24:39'),(12,'汝就做吾的犬吧','推荐','我反而倒是觉得第二部要比第一部精彩，至少第二部一直在围绕着主线剧情讲，除了那个魁地奇以外也没有什么多余的剧情，不过这个系列的人物和事件的展开都过于简单单调了，一般一开始留有最明显嫌疑的假设到最后都会被推翻，搞笑角色也永远只是一些搞笑角色，鲜有另一面的感情折射','2011-08-02 23:44:46'),(13,'Immortals','力荐','“让我们成为哪种人并不是我们的能力，而是我们的选择”——邓布利多','2021-01-26 23:21:48'),(14,'026后勤仓库','力荐','重温。第二部最大的细节就是在一切结束后，赫敏回归时和哈利拥抱，和罗恩握手。小时候并不觉得什么，长大后才发现原来对于心中的认定的好朋友不会在意自己的行为，没有过多的想法，而对于心中在意的人却极力克制自己的行为。也是为后续赫敏和罗恩在一起埋下伏笔。','2022-07-20 15:10:30'),(15,'依.然.饭.特.稀','力荐','好好看啊！！！以前我真的是瞎了眼了，，看着厚厚的书就烦，原来这么好看。　　好吧，我承认从现在开始我就是一位哈迷了。。　本集中Fawkes用眼泪为哈利治蛇毒的情景，好感人阿～～～　多比好可爱、好委屈阿，让人不由心生爱怜...　它的主人马尔福好可恶！！“Dobby is free!\"','2010-01-19 21:43:29');
