INSERT INTO `哈利_波特与火焰杯` VALUES (1,'花花','力荐','其实与原著相差挺大，但是记忆里第一次窝在被窝里看到赫敏走下台阶的那刻惊艳永远不忘。凭着这个都愿意给5星','2018-05-19 22:42:55'),(2,'同志亦凡人中文站','还行','发型和服装交给演员自己乱搞的结果...','2012-07-20 19:52:58'),(3,'Neroat','力荐','哈利波特系列最喜欢的一部，剧情最吸引人的一部。另外，克鲁姆很迷人。一如既往地爱着罗恩。','2014-11-17 09:38:33'),(4,'Nakedself','力荐','英国人把冒傻气的哈四演绎成了绝妙的青春戏剧，三人组的吵架，亲密得让人不好意思起来。而我最喜欢纳威。','2006-05-17 15:59:44'),(5,'tavico','力荐','目前为止这部最好看，不过可以想象书应该更精彩，尤其是斗龙那里','2009-07-26 16:11:05'),(6,'彩戏师','推荐','不管是书还是电影，火焰杯都是最好看的','2009-08-03 12:35:01'),(7,'和风莫吉托','推荐','感觉拍得最差的一部。初三在影院看完后你还找我借了书，记得不隔天上课时你捧着那本漂亮的绿皮书向后侧过身子指着描述穆迪假眼睛的那段对我笑得合不拢嘴。你让我多想亲你你知道不？','2011-03-15 23:46:15'),(8,'齐木楠雄','力荐','最喜欢这一集的魁地奇大赛','2016-10-21 15:27:11'),(9,'遇见彩虹?','推荐','剧情忘记了。赫敏越来越漂亮了，然后那两位越来越。。。','2018-04-17 15:23:13'),(10,'樹一','力荐','舞会上赫敏出场那一瞬间太太太太惊艳了！！！三强争霸赛也有诸多亮点，虽然这是进入黑暗基调的起点..','2011-09-02 00:34:53'),(11,'沉默的小皮','力荐','这一学年，学会了斗龙，学会了邀请女孩跳舞，学会真正面对死亡','2024-09-27 20:22:39'),(12,'鱼丸粗面','还行','150分钟的片子还是感觉太仓促。一些场景、道具比想象中的要简陋。','2006-07-19 15:06:38'),(13,'信电影得永生','推荐','这一集真心不错，青春期对异性的朦胧感觉切入，男生女生之间微妙的心理变化。波特接受挑战，内心开始成长。伏地魔复活，黑暗来临。好戏刚刚开始。片子还是感觉长，但因比较细腻，所以没那么无聊，说实话比赛好没劲儿，还好又节省的部分，从第三个比赛才开始紧凑起来。三星半','2013-10-01 21:24:16'),(14,'全都是风','推荐','每次看到第二轮比赛的时候哈利的珍宝是罗恩都笑翻了过去！','2014-06-11 23:01:25'),(15,'余生皆是假期！','力荐','塞德里克的死是个分水岭，昭示着魔法世界开始显露残酷和暗黑的一面，之后那种金碧辉煌、想象力纵横驰骋的快乐就少了很多。周日的傍晚，片尾曲响起的时候，我还迟迟不愿离开。因为一离开霍格沃茨，我又要成为工位的牛马，与之相比我更愿意参加火焰杯被龙追。','2024-11-03 20:09:29');
/*!40000 ALTER TABLE `哈利_波特与火焰杯` ENABLE KEYS */;
UNLOCK TABLES;

