INSERT INTO `哈利_波特与魔法石` VALUES (1,'根','力荐','一整个世界被打开了的感觉啊。','2012-01-12 13:48:27'),(2,'宅蘑菇Moku','力荐','还是第一部最可爱了，正太是正太萝莉是萝莉的','2007-09-27 00:04:51'),(3,'tavico','推荐','花了8年才看完这部电影....','2009-07-18 11:57:39'),(4,'墨语悠然','推荐','这部电影是刚上中学过最后一个六一的时候，学校给放的，太久远的记忆了。作者天马行空的想象力，电影精妙绝伦的现，让我第一次对想象中的“魔法”，有了一个具象的观感。虽然那是一个虚拟的世界，但是我不会忘记那份感动和震撼。九又四分之三站台，分院帽，格兰芬多，魁地奇，都是最精彩的记忆！','2016-12-15 18:44:45'),(5,'如小果','力荐','演员最好看的一部。','2010-12-15 16:42:40'),(6,'同志亦凡人中文站','力荐','忠实原著有时候未必就不能打造惊喜。','2012-07-20 19:53:40'),(7,'猫语猫寻','力荐','我觉得这仍然是这个系列里最好看的一集吧，第一次看的时候真的惊喜死了，整体设定的展开和铺陈都让人激动，重点是哈利在这个时候是最萌最可爱的时候了，第二集开始就慢慢的长开了！对！长！开！了！','2009-09-11 03:07:38'),(8,'44口口','力荐','那时候是有多可爱啊，刚接触魔法的种种新鲜和刺激，比起后面的黑暗剧情以及丹尼尔越来越大叔的模样，真是怀念这里啊。','2010-10-09 00:58:11'),(9,'遇见彩虹?','推荐','当年还是在电影院看的，波特的魔法世界惊艳展开，风靡全球。','2018-03-01 13:42:04'),(10,'AshtrayGem','力荐','第一部是最忠于原著的~而且第一次接触魔幻世界很受震撼~','2008-05-15 19:58:34'),(11,'Nakedself','力荐','你信不信，我也养了一只猫头鹰^^','2006-05-17 15:59:21'),(12,'偏要勉强','力荐','一个全新的世界被打开了，新奇而不可思议，我们都是麻瓜，幻想一天早上猫头鹰会送来霍格沃兹的入学通知书。铁三角组合很可爱。','2018-04-17 12:41:16'),(13,'StevenTong','力荐','我竟然還沒有在豆瓣添加哈利波特系列啊... 我怎麼當粉絲的我！第一部自然是最引人入勝的。','2009-06-10 02:11:51'),(14,'Morning','还行','作为HP系列的开篇，算是合格完成任务，对人物的交代都很清晰，在许多分裂的HP其他几部，这一部是最忠实表达魔法世界的异彩纷呈的，在交待情节的同时仍不忘学院里的幽灵，会动的画像和楼梯，这在后来几部都几乎没有了。','2011-07-14 15:17:45'),(15,'小耳朵图吗','力荐','第一部好看啊 时隔快20年 2020 0818 电影院看了3d','2006-08-21 20:15:02');
/*!40000 ALTER TABLE `哈利_波特与魔法石` ENABLE KEYS */;
