LOCK TABLES `城市之光` WRITE;
/*!40000 ALTER TABLE `城市之光` DISABLE KEYS */;
INSERT INTO `城市之光` VALUES (1,'李可笑','力荐','”假如我们长时间地、专注看一个好笑的故事，它会变得越来越悲哀“——果戈理','2012-04-17 23:22:43'),(2,'朝暮雪','力荐','卓别林兼任出品人、制作人、监制、导演、主演、配乐、剪辑，结果一个奥斯卡提名都没有。 卖花女一点不瞎，瞎的是奥斯卡评委。','2013-02-02 19:36:28'),(3,'小岩菽','力荐','老电影咖啡馆的第一弹。原来明天会更好的原文也可以是tomorrow the birds will sing。','2008-06-24 12:42:53'),(4,'U 兔','力荐','最后一个眼神的特写，直指人心','2009-01-05 14:31:15'),(5,'同志亦凡人中文站','力荐','爱情是光，将城市点亮，笑的最后却是感动。卓别林竟然是爱情电影的大师……','2014-11-14 05:04:57'),(6,'sanyo','力荐','盲女复明后认出流浪汉的一刻是影史上最难熬的一瞬。','2021-04-05 18:49:56'),(7,'米粒','力荐','哭哭笑笑的小人物传。里面的爱情可有千百种解读，就不赘述了。但爱情的确能让人变瞎，也能让人复明啊。拳击那场戏大赞。','2012-03-14 09:07:57'),(8,'尧耳','力荐','矮小的卓别林，伟大的卓别林。无论是幽默的桥段，还是整体的剧情，都透出经典气质，淳朴、踏实，然而持久。','2010-12-15 12:53:51'),(9,'影志','还行','不知道是看片情境不对，还是个人状态不佳，看完感触不多。','2013-06-12 23:28:47'),(10,'LORENZO 洛伦佐','力荐','幽幽城市之光，让我们相信人心中还有良善。完美的表演和动人的情节。镜头的切换和动作的编排很到位。30年代初就有如此细致的故事编排结构和表演的编导，卓别林真是位大师。','2011-01-10 09:39:32'),(11,'冰红深蓝','力荐','大半时间各种捧腹，结尾却忍不住落泪~不愧是卓别林，兼具批判性、幽默诙谐与暖洋洋的正能量！在查理最后一部默片中，流浪汉与卖花盲女的爱情不知感动了多少人；笑点源源不断，拳击戏更是无与伦比；结尾被评为影史最佳结尾。当代的肥皂剧有几个能达到这种笑中带泪的喜剧片最高境界？（9.5/10）','2014-07-31 00:43:38'),(12,'阿巴厮','力荐','嘻嘻笑笑，最后真动人，原以为会错过而不相识，但是这样的遗憾多不应该出现啊，所以，结局真好。','2013-02-26 21:26:49'),(13,'冰山李','力荐','9.1；當天街角流過你聲線，沿路旅程如歌褪變','2011-11-07 14:25:38'),(14,'有心打扰','力荐','未来是美好的，人间总有真情，别放弃骚扰生活。','2012-02-11 22:36:48'),(15,'粟熙','力荐','是哪本教科书里说的我忘了，喜剧用全景，悲剧用特写。所以看完大量的全景后，结尾卓别林来了一个大大的特写，令人难忘的哀伤眼神。','2008-04-29 23:23:52');
/*!40000 ALTER TABLE `城市之光` ENABLE KEYS */;
UNLOCK TABLES;

