INSERT INTO `大红灯笼高高挂` VALUES (1,'战国客','推荐','那个从未露面的老爷真是设计巧妙~~','2008-03-02 22:17:09'),(2,'露水十一','力荐','以前的娱乐活动还是少，才有了大红灯笼的悲剧。换这会一个太太给台电脑上个网。谁管你老爷来不来啊','2011-08-09 18:08:20'),(3,'胡克','推荐','这片之后让我对总是满脸笑意过分热情的各种阿姨十分抵触','2007-04-14 10:47:50'),(4,'Ragdoll™','推荐','大太太甘于沉寂二太太活得太累三太太通透了了仍是戏散曲终空繁华一场四太太清高拿劲儿迫从流俗不知道自己想要什么想要了又止于落目该出招时不出招不该出招瞎得瑟害人害己纠结矛盾不知惜命疯有可缘 雁儿最可怜 心比墙头瓦高命比灯笼纸薄 败在倔强毁在看不开 深宅大院未必封建云云 不过缩影尘世冷暖罢了','2010-12-14 11:37:16'),(5,'SASKIA','推荐','小時候，你看電影，只是看，很多電影，你長大后，應該再看一次。','2012-08-26 02:07:52'),(6,'bird','力荐','张艺谋没给最大的爷一个正脸镜头，这才是谋子最棒的片。','2014-05-16 23:14:25'),(7,'同志亦凡人中文站','推荐','工整对称的画面美学，本身即像封建宗法所谓的规矩。 符号隐喻多得不寒而栗。国师那时的叙事真是简洁啊，好多内容直接就用红灯笼和梆子声交代了。','2014-05-26 16:13:19'),(8,'林||我们谈什么都像谈死！','推荐','捶脚那个性寓意太浓了。监制是侯孝贤。','2009-05-16 14:33:10'),(9,'彌張','力荐','太爱那悲凉的气氛了。尤其是清晨三太太在屋顶唱戏，美到极致了！','2009-06-08 11:15:21'),(10,'火娃','推荐','8/10。出嫁时颂莲故意与迎亲的花轿背道而行象征读书人的清高，刚开始嫌弃捶脚这种权力的符号但逐渐因为虚荣参与权力争斗，高墙大院的对称构图吞噬了颂莲的本性，老爷烧掉遗父的笛子也一种吞噬(自由)，初夜老爷离开后她举着灯照见镜子中本性扭曲的自我形象；死人屋和借酒成疯背后隐藏的恐怖韵味很独特。 @2017-07-29 23:27:54','2017-07-29 23:27:54'),(11,'süden','推荐','严重推荐外景拍摄地乔家大院，大家有空去玩罢~','2006-06-09 17:01:25'),(12,'无事请旁观','推荐','老爷从来没露过面，但是他教育你、定义你、疼爱你、赏赐你、审视你、批判你、甚至杀死你，你都毫无反抗之力，老爷是谁并不重要，重要的是他是一个掌握权力和财富的男人，他可以不在，但是他无处不在。深宅大院不过是父权制男性的炫耀和女性的牢笼。','2023-07-28 09:41:58'),(13,'shininglove','力荐','大雪纷飞没古城，深墙大院要掌灯。三妻四妾死人井，疑是红颜殒葬声。','2015-07-26 02:37:10'),(14,'峰峰峰峰','推荐','点灯，灭灯，封灯，在这院里，人算个什么东西？人跟鬼就差一口气，人就是鬼，鬼就是人。你算计我，我算计你，从夏到冬，这是个没有春的故事。','2014-04-06 21:00:21'),(15,'浅。','推荐','庭院深深深几许？','2008-03-19 17:45:53');
/*!40000 ALTER TABLE `大红灯笼高高挂` ENABLE KEYS */;
