LOCK TABLES `大闹天宫` WRITE;
/*!40000 ALTER TABLE `大闹天宫` DISABLE KEYS */;
INSERT INTO `大闹天宫` VALUES (1,'Over5','力荐','堪比业界史上的两弹一星，这个猴子是我们国产动画片的骄傲，但到了今天依然得指望着它说事儿～','2007-03-17 18:46:20'),(2,'有病的乃提乃','力荐','50年过去了，中国动画不进反退，还有比这更可悲的事么。技术上止步不前，创意上才思枯竭。一群羊和两只狼的故事都被反复翻炒出N部，悲矣；当年号称十年巨制制出一部宝莲灯，贻笑大方矣。现在小孩的物质条件比我们好了n倍，但是我仍然觉得当年的我们是幸福的，因为有这么多优秀的动画片陪伴成长。','2011-04-24 03:57:26'),(3,'战国客','推荐','向中国早期的动画制作人员致敬！','2009-04-23 18:15:42'),(4,'汪金卫','推荐','要看就看影迷修复版，那是最好的版本。比官方的所谓40周年纪念版都好。玉帝的下巴上非常明显的有颗痣我会到处乱说吗？','2012-01-18 18:20:57'),(5,'蓝下老婆','推荐','永远的经典','2017-04-04 21:33:20'),(6,'寒枝雀静','推荐','B / 文本内含复杂性，但是叙述的语调缺乏复杂性。几乎是将孙悟空当做一个完全的超级英雄来描绘，且大多只是通过表层的“行动”来描绘，而情绪什么的几乎是不存在的。至于孙悟空为什么总是表面不屑但却内心艳羡天庭，为什么会对“正名”有如此执拗的追求，为什么一个野性难驯的孙悟空还要嫌天庭“暗箭伤人”，都基本没有更深层更隐约的指向。当然，这大概就是截取一段拍出来的劣势所在，毕竟“西游”就是一个孙悟空不断下沉的过程。流光溢彩到最后都有点审美疲劳。','2019-07-20 17:31:26'),(7,'巴喆','力荐','1961年，中国大陆，全手工，此片原画历时4年，10分钟的动画镜头要画7000到1万张原画。文革时期此片被批斗为牛鬼蛇神，是流氓无赖的化身。当时运动每天都在升级，全国的“猴子戏”都被禁演了，万籁鸣也被关起来了。日本“漫画之神”，动画漫画始祖手冢治虫本人承认正是看了万氏兄弟的《铁扇公主》，他才弃医从事动漫事业，才有了后来的《阿童木》。中国的动画曾经领先亚洲，我绝对没夸张。9.5','2012-10-17 10:55:56'),(8,'我lu不会飞','推荐','最早的，也是最好的，向经典致敬','2017-04-04 21:31:57'),(9,'Odding','力荐','这个无须评论。','2006-03-26 14:03:45'),(10,'苏幼','推荐','好看！！好看！！好看！！，重要的事情说三遍！','2017-04-30 17:11:53'),(11,'把噗','无评分','经典','2011-08-31 20:17:45'),(12,'老阿飞—故园','力荐','中国动画=大闹天空，虽然对很多动画来说这样很不公平，但是，你能找出其他这么有代表性的佳作？','2006-01-08 17:21:11'),(13,'IlTrovatore','力荐','中国动画难以逾越的一部','2010-02-09 16:34:34'),(14,'17950','力荐','真纯粹的中国动画','2006-10-15 14:14:05'),(15,'同志亦凡人中文站','力荐','反抗，反抗，再反抗','2012-12-14 22:12:19');
/*!40000 ALTER TABLE `大闹天宫` ENABLE KEYS */;
UNLOCK TABLES;

