INSERT INTO `天使爱美丽` VALUES (1,'小痕呀','推荐','浪漫到骨子里，忧郁，神经质，跳跃，文艺是很典型的法国电影啊！喜欢的人为它如痴如醉，不喜欢的人看的昏昏欲睡，两种极端。我只能说非常好，非常适合一遍一遍地欣赏。艾米丽是天使，拥抱世人，容纳那些不美好。','2017-03-22 15:24:30'),(2,'宋小君','推荐','浓重的法国情调，舒缓，镜头语言动听。女主角漂亮。唯一的不足就是……这样的爱情会不会太作了？爱情就是门口经过的大巴，现在不上，以后都不能再上了……','2012-01-09 10:08:47'),(3,'Zephyrance','力荐','左上唇，右脸颊，左眼，右后脖颈。','2006-07-29 12:20:38'),(4,'大头绿豆','力荐','艾米丽扶着那个盲老头走过马路和天桥和无数商店，飞快地告诉他自己看到了什么，然后又像天使一样离开。','2005-06-12 02:22:17'),(5,'赫恩曼尼','推荐','没有你，良辰美景奈何？法国式的温馨神秘，爱死了的爱情','2012-07-24 22:31:16'),(6,'郑／','无评分','其实我也经常做这样的事情，为什么拍成电影就有人赞好，现实当中被当成白痴','2011-06-12 16:12:26'),(7,'X','推荐','喜欢奥黛丽塔图，有一种纯真的狡黠','2017-03-20 10:54:44'),(8,'流浪忧伤','力荐','有没有人觉得和重庆深林里的王菲有点相似？','2011-01-06 20:25:38'),(9,'文泽尔','还行','配乐大好，剪辑大好.别的不够好. 至少不对胃口 到现在只对片子最开始的部分 也即艾米莉的自述印象深刻了 尝试做爱如何，但是感觉不太好. 那个微笑的表情','2007-09-19 22:45:03'),(10,'寂地','力荐','看了心情会很好','2006-01-01 17:46:23'),(11,'süden','还行','看名字就不怎么想看的一部片子，果然片子色彩那么美，女主角长得也不错，性格很萝莉，但就是不喜欢。她整水果摊老板的手段太刻薄了','2009-01-05 22:07:58'),(12,'Ocap','推荐','讲给宅女听的现代童话，极致光影美，讨喜伪浪漫。让-皮埃尔·热内以随性诠释感性，就像摆脱了强迫症的韦斯·安德森，大师耍稚气。如果说好看、动听、可回味的电影并不一定需要好故事，那么本片就是明证，法式风情渗透在它每一个镜头的每一个角落里，帧帧如画，迷人而另类。','2015-05-17 16:23:06'),(13,'李丝丝','无评分','我不喜欢这个女人的','2007-03-04 22:17:50'),(14,'橘猫爱吃鱼','推荐','奥黛丽•塔图很完美的演绎了“艾美丽”这一角色，表演十分的到位，在古灵精怪的同时又很富有柔情与少女的情怀，十分的完美。','2018-04-18 07:18:49'),(15,'幸存者','推荐','人生确实奇妙，小时候总嫌时间过得慢，一眨眼你已50岁了。童年回忆，只能靠旧盒子里的东西勾起。我现在已经30岁了，回想时间，过时觉得慢，现在却觉过得挺快的！爸妈都已头发发白，爷爷离我们远去了！','2018-04-16 21:11:44');
/*!40000 ALTER TABLE `天使爱美丽` ENABLE KEYS */;
UNLOCK TABLES;

