INSERT INTO `当幸福来敲门` VALUES (1,'Zia','力荐','如果能让自己不再为光阴被虚度，才华被耗尽而流泪，如果能让自己坚定，“我不要似是而非的人生，我要自己做的每一件事都刻骨铭心”，那么这场狂热便是得其所，记住这永远不是最差的人生。','2009-08-09 19:33:17'),(2,'囍夭夭','推荐','看到开头就知道结局，不过这并不重要，重要的是过程。。。最感人的不是赢得职位，而是在厕所里捂住儿子的耳朵。。。作为一名容易感情用事的中国观众，感动比励志对我来说更重要=。=','2009-04-06 20:40:29'),(3,'小没','推荐','我一直记得，有人对我说：当你迈过这个坎之后，你会发现，还会有什么不可以面对的困难。','2008-02-12 19:07:33'),(4,'水木丁','力荐','虽然是个好莱坞励志片，但真正让我感慨的其实是，穷人想要翻身，真是太难太难了，他们大多数不是不努力工作，但确实是一根绳子勒在脖子上，压根没有喘息的机会，而且他们的孩子从出生下来就没有，毕竟不是每个穷人家的孩子，都足够幸运能有这么顽强，比别人聪明十倍的爸爸啊。','2015-03-08 15:31:34'),(5,'曾经','推荐','有点失望...感觉是为了励志而励志......要不是导演和演员功力，就沦落成俗套励志片了......','2010-01-22 23:46:32'),(6,'luc1en','无评分','不是幸福来敲门，而是死皮赖脸敲幸福家的门，直到幸福来开门','2009-06-09 01:25:45'),(7,'树木希凉','推荐','失业时候看的,简直是催泪弹,WILL的儿子将来一定是块料,奥斯卡上看他跟小美女打闹,忒逗.','2007-04-28 19:30:46'),(8,'shield','推荐','就算身在阶级底层，父亲也极力让儿子相信世界并不是那么残酷无情，故事非常感人。','2017-01-05 18:11:19'),(9,'疤疤爸爸','力荐','为毛不去天桥上乞讨？为毛不去地铁里乞讨？在我们这儿是这么办的。','2009-08-23 12:15:59'),(10,'sharon','推荐','看到男主最困难的时候去捐血换吃食，带着西装上班，特别心酸，而这份难受的对比使得美好结局更激动人心','2017-03-19 22:39:56'),(11,'半袖','力荐','孩子母亲颤抖着说你会照顾好他； 装扮成时光机器来安抚孩子，子夜洗手间中独自哭泣； “你是个好爸爸”，孩子说。 看电影的时候，我的手经常不自觉的紧握着，为那揪心的困窘。 幸福在这里敲门了，可是那些没有被敲门的人呢？','2007-01-28 00:42:12'),(12,'天亮天黑','力荐','生活时常会让我们感到艰辛，并会让我们无数次目睹生命在各种重压下的扭曲与变形。——《生命不可承受之轻》','2010-11-10 20:38:55'),(13,'小海','力荐','想起来徐本禹说的那句话：”你穷，别人会同情你，但你一直穷，别人不会一直同情你的。“《幸福来敲门》虽然算不上是完美的励志片，但它至少教会我一点，不要把自己经历过的事儿当个事儿，即使能感动他人，这些也什么都不是。把这些扔在脑后，让生命爆发出战斗力，去击败一切，才是真正动人的感人故事。','2012-04-04 18:24:29'),(14,'Over5','还行','睡在厕所的父子，有人被尿憋死在门外～哎～','2009-01-11 20:48:02'),(15,'张樾','推荐','总会找到一个上帝，端坐天堂。','2008-02-17 09:53:47');
/*!40000 ALTER TABLE `当幸福来敲门` ENABLE KEYS */;
UNLOCK TABLES;

