INSERT INTO `惊魂记` VALUES (1,'远子','还行','希区柯克这回出现得太早了点，让观影的乐趣一下子降了不少。还有最后那个心理医生那趾高气扬的神情让人很不舒服。','2014-05-03 14:16:00'),(2,'昏金暗玉','力荐','看这部电影必须回答一个经典的问题：女主角遭到刺杀时，镜头直面花洒，花洒每一条水痕都清晰无误如同肉眼看着一样上镜。请问，摄影机是如何做到的？','2008-09-18 14:52:42'),(3,'Doublebitch','力荐','人格分裂的鼻祖，试想60年代人们看到这部电影时能有几个不喊牛逼的','2011-01-18 17:19:49'),(4,'塞塞','推荐','且看诺曼的last smile 毛骨悚然！','2008-05-03 12:41:41'),(5,'17950','力荐','神作。全面滿分。如果有任何不被打動的理由，那就是觀眾晚生了50年，受到太多這部電影50年來泛濫的影響，就像一個沒有受過高等教育的英國老婦不會覺得沙劇牛逼一樣。','2010-11-13 23:15:39'),(6,'影志','力荐','“一个男孩最好的朋友就是他母亲” 诺曼上楼扭屁股…等细节虽然早就猜到了结局，但今天第一次看依然被震撼到。','2019-04-15 15:40:02'),(7,'同志亦凡人中文站','力荐','剧本和细节真是绝了，对性别的理解更是超前时代。万圣节去看希区柯克就是no zuo no die的节奏，惊恐交加中居然错抓了邻座小哥的手... o(>﹏<)o','2014-10-31 17:56:08'),(8,'孙此方','推荐','最后那一抹笑容堪称经典','2012-09-26 00:17:04'),(9,'Spotless Mind','力荐','80W成本的电影业同样可以做到流芳百世，希区柯克缜密的思维、独特的运镜，加重了对细节的刻画，其隐喻也值得回味，结尾那具骷髅头更让人不寒而栗。据说此片开创了人格分裂电影的先河，同时也暗示了希区柯克本人的“厌女癖”。','2010-01-15 21:45:39'),(10,'根','力荐','妈呀，（影史）知名酒店竟用拖把清洗浴缸！！','2019-08-18 23:59:22'),(11,'文泽尔','力荐','老希让人最意想不到的悬疑经典之一。将故事串联起来，本来以为会是与这件事相关，但最终却变成了旅馆中的凶杀：对母亲话语唯命是从的儿子。然后竟又将一切推翻，转变为警局中冰冷的表述。经典的镜头：雨中行车（这里迎接了转变），浴室谋杀（唯美），早已死去的XX的骷髅孔洞的双眼（最大震撼）','2007-12-18 23:18:21'),(12,'1874','力荐','b站弹幕太好笑了：4w-700居然还用列竖式','2021-03-03 01:23:31'),(13,'杂技演员','推荐','\"伪\"的就是\"娘\"！','2010-10-27 10:57:19'),(14,'狷介有乌青','力荐','细节部分处理地相当细腻，特别是母亲房间和儿子房间的对比。这片对于几重人格及犯罪后心理创伤的运用对后世影响颇大，犯罪心理里有一集也是杀人狂儿子将母亲的遗骨保留到发霉，韩国那部老师的恩惠也是。','2009-08-14 00:10:27'),(15,'战国客','力荐','紧张的气氛营造得真棒！！！','2009-10-17 23:05:16');
/*!40000 ALTER TABLE `惊魂记` ENABLE KEYS */;
UNLOCK TABLES;

