LOCK TABLES `我不是药神` WRITE;
/*!40000 ALTER TABLE `我不是药神` DISABLE KEYS */;
INSERT INTO `我不是药神` VALUES (1,'袁牧','推荐','看了一下差评，基本是自诩为独立专业的几个影评人给的吧，果然又要说电影语言，商业媚俗之类，固然把这个题材拍成侯孝贤、蔡明亮那样，影评人会有高潮，但你们其实喜欢的是影院里就坐着你们两三个人那种感觉不是吗？没有这种电影，电影人在时代急速抛弃弱势群体的巨变中，就是完全失语的。','2018-07-06 16:58:09'),(2,'亵渎电影','推荐','我就是想实名表扬一下王传君，内地青年演员里竟然也有这种会演戏并且很卖力的实力派演员，这要是搁在好莱坞，他能拿下一座奥斯卡最佳男配。像这样的现实主义题材电影，如果编剧不是韩家女，它可能连拍摄许可证都拿不到，过审更没戏，它在国内的审查制度下没有可复制性，像这样的电影，且看且珍惜吧！','2018-07-07 20:43:27'),(3,'frozenmoon','推荐','不涂彩不抹粉不抛光，近年来少见的现实主义力作。更可贵的是，清清楚楚地写中国的事，写印度的事，清清楚楚地表明这是上海，车牌上大大方方印着沪，而现在很多电影已经愈发架空现实了。战争题材写到恐怖分子得虚构一个不存在的国家，犯罪题材得虚构一个不存在的城市。《药神》为中国现实主义挽回尊严。','2018-06-30 19:53:11'),(4,'沐子荒','力荐','王传君所有不被外人理解的坚持，都在这一刻得到了完美释放。他不是关谷神奇，他是王传君。 你看，即使依旧烂片如云，只要还有哪怕极少的人坚持，中国影视也终于还是从中生出了茁壮的根。 我不是药神，治不好这世界。但能改变一点，总归是会好的。','2018-07-03 22:37:38'),(5,'朝暮雪','力荐','这不是“中国版《达拉斯买家俱乐部》”，这是中国的真实事件改编的中国电影，是属于我们自己的电影，不知道就去百度一下“陆勇”。','2018-06-30 17:40:18'),(6,'开开kerguelen','力荐','小时候路过一家药店，门口的对联写着“只愿世间无疾病，何愁架上药染尘”','2018-07-04 21:00:31'),(7,'七海','力荐','文牧野眼睛太毒了，观众的笑点、泪点、痛点被他牢牢抓住，徐峥现在不拼演技开始掏心炸肺放脱自我了，药物在中国绝对是个“不可说”，但这个电影说了它能说的，也不显山不漏水的说了它所不能说的，讲的是现实，但看过电影之后才会明白其实是超现实，2018最佳!','2018-06-30 19:28:36'),(8,'大島','力荐','你的一个举动可能会改变别人的一生，酒吧领班从此爱上了钢管舞。','2018-07-05 21:39:15'),(9,'Noodles','力荐','人生建议：别买零食，吃不下的。','2018-07-03 23:58:30'),(10,'喝可乐的鸟','力荐','炸裂，哭成狗，从观影体验上看，比达拉斯买家俱乐部好，之间隔了差不多五个《动物世界》，导演处女作就这完成度，只能说剧本实在太好。我爸爸也是药神的受益者之一，否则我应该房子也没了。感谢他们?。','2018-07-03 22:01:56'),(11,'谢谢你们的鱼','推荐','它远远不够好，但是对于现在的中国电影市场来说，它又好得要命。','2018-07-03 21:26:54'),(12,'根','推荐','无法想象下一部这样的电影会是什么题材、能是什么题材，感觉就像是领受了上头扔下来的一根肉骨头一样。王传君真的太好了，周一围最后靠在车上等人的那一幕帅得我愿意为他入狱三年……','2018-07-10 23:16:11'),(13,'谢飞导演','力荐','祝贺学院硕士毕业生文牧野出手不凡，导演了这样一部扎实、感人、有见地的处女作！看片中常在想：在疾病、死亡面前，一些常规的道义、是非怎么都成了反意？先人说过“合情合理才是好法。”那么实践证明已经不合情理的法律规章就应该改掉它！直面现实，促人思索，这样的作品值得夸赞！','2018-07-10 15:44:56'),(14,'羚羊的灵魂','推荐','我一直以为牧师是金士杰演的哈哈哈哈哈哈竟然不是','2018-06-30 17:26:59'),(15,'艺艺艺仔','推荐','懦弱、贪财、甚至家暴的小人物，最后却咬着牙把善事做到底——其实大部分人都是这样，即非至纯至善，也非穷凶极恶，但是看见了，没办法假装没看见。','2018-07-04 23:02:46');
/*!40000 ALTER TABLE `我不是药神` ENABLE KEYS */;
UNLOCK TABLES;

