/*!40000 ALTER TABLE `拯救大兵瑞恩` DISABLE KEYS */;
INSERT INTO `拯救大兵瑞恩` VALUES (1,'Yanisk','力荐','如果没有办法想起他什么样子，就试着想想和他共渡的时光。','2011-12-29 12:12:24'),(2,'容安','推荐','厄本这个角色很有意思，懦弱，非常懦弱，还有一种可笑的浪漫和无知的善良。他才是你我他，对战争的残酷抱有一种可耻的畏惧，并对其有好心的幻想。可惜事实并非如此，战争就是你死我活，战争是考验勇气的时刻，而非善心。胆小的也许能活下来，但在战争中，你已经输了。而那些死了的勇士，他们才是胜利者','2011-02-28 22:41:26'),(3,'魏无忌','力荐','战争电影No1，美利坚精神输出大片。','2008-07-06 23:23:52'),(4,'.Aмаиdα.','力荐','我心目中的永恒经典。不知道集结号借用了他多少情节。反正不少。','2008-03-30 23:21:14'),(5,'Obtson','力荐','真正意义的大导大片，开场的抢滩和结尾的瑞梅尔血战机位控制臻入神技，牛逼的主次特写像一位幸存的二战联盟老兵啐着唾沫在回忆戎马。瑞梅尔的残破桥头，米勒上尉的身后是无尽残阳，他的面前是这个略显荒谬任务的完结，他的面前也是詹姆斯瑞恩的明天。','2011-01-15 19:00:58'),(6,'影志','力荐','看到结尾Hanks无力地对着迎面驶来的坦克，内奔…过好此生，就是最大的“不辜负”。','2005-08-24 07:22:25'),(7,'L.','推荐','为什么看中国战争片就感觉high得不行真想打一仗，看外国战争片就觉得战争真可怕和平多好啊。。。。再不在吃饭的时候看战争片了，太胸闷了。','2012-10-20 20:27:09'),(8,'托尼·王大拿','力荐','那些近乎白描式的战役刻画，真实而震撼；米勒中尉不由自主颤抖的手，是那时每个如棋子般无法控制自己命运战士的写照；在更高层面上的人性与伦理的探讨，其实已经无关紧要。','2014-12-19 02:54:12'),(9,'###疼','力荐','有一個小細節我很喜歡...將要下雨的時候..鏡頭給了湖水,葉子..水滴一滴一滴地落在湖水上,,之後變得密集..就好像槍林彈雨前的感覺,,,好佩服皮爾斯伯格對電影的構思和湯姆漢克斯的演技,,一部偉大的作品!','2010-12-04 18:06:38'),(10,'寂地','还行','其实电影非常的棒，但是道理和萤火虫之墓地一样．因为实在太真实，让人难受．看到一半就缩到了角落里，再也不想看下去．','2006-01-05 00:20:43'),(11,'已 注销','力荐','给我打死那个翻译官','2021-01-25 22:04:07'),(12,'烬。','力荐','比血战钢锯岭高出10个段位。其实剧本还是很工整的，有些匠气的痕迹，但是节奏快慢的间歇拿捏的特别好，剧本台词超棒，细节对于人物形象的凸显到位。没有说教，没有煽情，只有人物与情节的推进，好电影。最爱战争前那段休息时刻，生死关头前的平静祥和，惨烈前的美好，最令人心碎。','2018-04-16 11:46:38'),(13,'麻雀一只','力荐','哭死我了，真的哭的我眼睛都肿了','2008-12-04 22:46:10'),(14,'旧书君','力荐','开场25分钟诺曼底登陆再现是斯老的高度，一些实摄手法甚至有些琢磨不透。群戏无争，各自出彩。这是属于那种放上十多年再回头看，也感觉不出时代流逝的电影，斯老用二战电影场面的标杆把故事定格在了历史以及影史之中。','2010-12-19 17:55:14'),(15,'stknight','力荐','获得了第71届奥斯卡最佳导演、最佳摄影、最佳录音、最佳剪辑、最佳音效五项大奖，已成为战争片里程碑式作品。影片重现了50多年前惊天动地的诺曼底登陆战的恢宏场面，让人惊骇的目睹了战争的激烈和残酷，被认为是有史以来最逼真的战争片之一。许多二战老兵对影片给予了极高评价','2009-01-31 15:40:32');
/*!40000 ALTER TABLE `拯救大兵瑞恩` ENABLE KEYS */;
