INSERT INTO `指环王3_王者无敌` VALUES (1,'无所谓','推荐','我就不明白甘道夫升级为白袍巫师了怎么不爱使魔法，改成肉搏战士了。一直期待他使一招毁天灭地……','2010-06-21 23:33:10'),(2,'如小果','力荐','即使在一起喝过多少次酒，逛过多少次街，掏过多少次心窝，共度过多少时光，许多人还是没能拥有一个能背起你从地狱走向天堂的朋友——山姆。','2011-09-07 22:24:43'),(3,'草威','力荐','最服的就是山姆了，走了那么长的路，路上吃得那么少，一点儿没瘦。','2017-01-09 22:13:52'),(4,'饭夫斯基','力荐','骑白马的不一定是王子，是甘道夫；精灵战斗的时候，导演不会毁了他的美貌，别提莱戈拉斯了；裹着蜘蛛丝的弗罗多就像埃及艳后克娄巴特拉；胖子是重要的，他们可以背你；俩人被困在末日火山上，我说要有鹰，于是有鹰了；我差点以为阿拉贡要迎娶莱戈拉斯；弗罗多和山姆是真爱，绝逼的真爱。我要再看原著。','2011-10-16 21:29:18'),(5,'红豆♥','无评分','甘道夫用魔杖驱除魔鸟时异常感动。 我觉得男主角是傻逼呢。山姆多好。山姆又温厚又忠诚又善良。 我爱山姆~~ 另外精灵们实在是太美了。精灵王子打翻大象时太帅了。矮人说的那句话“这样也只能算一个”也好有爱哈哈。','2011-01-20 01:35:58'),(6,'Qing','推荐','不知为何很不喜欢霍比特人那条线……拖沓啰嗦 但又不能不要 人皇那条线最喜欢了 真正的气势磅礴（P.S.从冰火追过来发现魔戒当真是真善美极了（P.P.S.甘道夫升级之后为什么还是用法杖打人 一直在等着他念咒语发大招荡平敌军来着','2017-04-07 13:34:56'),(7,'A-sun*','推荐','亡灵奔涌那里很帅••••••','2012-04-04 13:28:15'),(8,'眼角的花朵','力荐','与咕鲁相比，弗罗多是幸运的。他具有别人无可比拟的强大的纯真力量。但他毁灭了魔戒，却无法清除内心被唤醒的邪恶。谁能说在故事最后他远渡海外，不是一种高傲的自我放逐？也许在索伦被消灭的那一刻，他也明白了邪恶的不可战胜。只是不得不与之抗争是英雄的使命。','2008-06-24 16:55:45'),(9,'susu/苏酱','力荐','要是让peter jackson来拍西游记，会怎样？？','2006-01-16 21:43:15'),(10,'颜良辰','力荐','每次看魔戒都会被奥兰度惊艳到~','2010-03-05 00:18:50'),(11,'格子','力荐','终于结束了，一切如常，我却回不去了','2008-11-17 19:03:15'),(12,'jj73浅之','力荐','原来真的可以被友情、信念和正义给感动。。。','2010-10-24 12:29:54'),(13,'雪後寒','力荐','阿拉贡20年没洗头了，还是帅得一如既往；我只要2天不洗头，就跟咕噜一样[苦涩][苦涩][苦涩]','2021-05-16 21:12:28'),(14,'螺丝இ','力荐','巨制就是巨制魔幻这题材少了美刀那不是人玩的感想如下：幽灵大军战斗力堪称最强阿拉贡你早调人马来省事好多 就是看着像清鼻涕 甘道夫你这个白袍儿怎么灰头土脸没有人家萨鲁曼当得有气势捏？精灵弓箭手萌~萌~萌~一大笑点是矮人金利 四个霍比特人就数弗罗多不讨喜这是角色设定没有办法 嫁人就嫁阿拉贡介样的人不过丽芙你脸也太长了我设定成宽屏还盛不下你的脸 有人说山姆和弗罗多其实是断背我看很有根据 所谓那会心一笑一切都明了 那额头一吻你别再敲打我心门 额我又腐了 最后压轴凯特你粲然一笑我瞬间倾倒！总结：60块收这6张D9值','2009-06-28 02:46:16'),(15,'束','力荐','一口气看完三部白金加长版，对于这样的片子，只有两个字形容：经典。相对于骇客帝国，这三部的连续性非常好，值得称赞。','2007-11-22 02:59:49');
