LOCK TABLES `攻壳机动队` WRITE;
/*!40000 ALTER TABLE `攻壳机动队` DISABLE KEYS */;
INSERT INTO `攻壳机动队` VALUES (1,'粟熙','力荐','剧情是晦涩的，场景描绘是牛B的，音乐是难以忘怀的，意义是划时代的。','2009-03-18 19:48:18'),(2,'一一','推荐','7.5/7.9 我想押井守做为一个日本人他与西方人截然不同的是他意识到操纵这个未来世界的不是华丽的想象，不可思议的科技或者是花哨的打斗，而是人本身理智与感性的不断矛盾冲突，这个冲突在物质化世界所激发的人的情感上的忧伤与绝望将缠绕人的灵魂久久不能散去，无论他们的肉体是如何铁一般强硬。','2009-06-17 04:06:06'),(3,'同志亦凡人中文站','力荐','革命性动画，看到了后来“黑客帝国”、“盗梦空间”等片的雏形。关于生命体的进化和繁衍、人类意识的植入和剥离，充满后现代的哲学思考。震撼！','2016-09-16 08:57:54'),(4,'匡轶歌','推荐','《攻壳机动队》从《神经漫游者》《银翼杀手》扒梗，《黑客帝国》又从《攻壳》扒梗…，徒子徒孙一片繁荣之际，作为 cyber punk 开山老祖宗的《神经漫游者》却直至现在都没有被拍成电影…然后还有一帮无知的瓜娃子读过小说后埋怨它“太过时”。啊呸！它不是“过时”，是【太超前】，是开创和预见了一个时代，好吗？','2015-06-29 19:47:13'),(5,'战国客','推荐','这还是动画片吗？','2009-04-04 16:33:21'),(6,'女儿吃鸡腿联会','推荐','想完全看懂还真有点难度','2011-04-25 12:41:58'),(7,'UrthónaD\'Mors','推荐','看看头就知道要给怎样的评分了，其中某些场景很银翼杀手的感觉。色调是偏冷的，人物或者说傀儡复制人是没有生命而空洞的但看到最后被撕裂被爆头还是有一种心痛感。','2011-05-13 15:19:35'),(8,'欢乐分裂','推荐','#SIFF#主题曲泛起，浑身鸡皮疙瘩，末世荒凉气氛，不乏妖冶迷离，配合香港雨夜，具有摧枯拉朽的美；超越既定界限的大生命观，记忆、灵魂以及意志，都具有独立人格和生存空间，对「生命」意义的终极探索；缺点是太短了，看不过瘾，比真人版好看100倍。','2017-06-22 20:21:40'),(9,'荞麦','力荐','1995年的作品，确实是神作。但印象最深的是配乐，尤其是一段毫无意义的破败街景配合着音乐和雨……在科幻中运用非常传统的日式配乐和声音真的太棒了。','2016-03-05 23:57:00'),(10,'桃桃林林','力荐','我来晚了','2007-09-02 11:33:09'),(11,'Aloysha','推荐','最棒的一点是九课组员中那个有家室、尚未义体化的菜鸟，素子说他的存在是为了不让九课走向极端特殊化。这是一种“普遍”的平等，人的主体性在片中当然是消解的，但也不代表科技成为了主体性的对立面，体制才是。你以为是科学伦理问题，其实还是体制问题。这一方面我甚至觉得优于《银翼杀手》，前者更多还是黑色电影的基底，但有超越性的美学建造；《攻壳机动队》中，素子大量的特写都是以星港城市为背景，而且与菜鸟的互动远超剧情需要，着重强调的是环境/体制对于素子人格的再塑造。最烦的一点是非得靠对白或者独白交代信息，还有主题。','2021-09-27 22:40:45'),(12,'风中奇缘','推荐','片中对话夹杂有很多进化论、生命定义、自我意识、AI独立人格、宗教伦理的哲学讨论，放到如今，也是具有现实意义的。格斗动作的设计干净利落。印象比较深的是，大量使用类似香港城市街区风貌的建筑设计，五花八门的中文广告牌，加上独特的配乐，营造出冷漠诡异的氛围。 但有一点不理解，女主角素子为什么每次都要裸体格斗，而男性角色就可以穿件衣服隐身呢？为什么在制造义体时，需要造出来逼真的乳房和乳头？它们并没有分泌乳汁，这项生物意义上的功能。','2025-05-07 12:07:37'),(13,'伊谢尔伦的风','力荐','巴特第一次被甩。','2011-04-13 13:47:53'),(14,'木卫二','力荐','你中有我、我中有你的存在困惑，造福人工智能题材的经典电影母题，新与旧融合的香港城市灵魂，深水静流的川井宪次配乐……中间起《傀儡谣》的疏影摇曳雨中城市，制造出了凝视深渊的人类命运忧伤。','2007-05-26 20:26:20'),(15,'陳小野','推荐','并不是这么难懂的，甚至可以说很好懂——太明显了，但也说明需要发现的还有很多......值得再看一次，最好看一下漫画','2006-09-22 21:15:16');
/*!40000 ALTER TABLE `攻壳机动队` ENABLE KEYS */;
UNLOCK TABLES;

