/*!40000 ALTER TABLE `新龙门客栈` DISABLE KEYS */;
INSERT INTO `新龙门客栈` VALUES (1,'MaTown','推荐','当年看到最后把甄子丹的脚剃成骨头的时候我还吓了一跳','2008-12-26 14:48:23'),(2,'王稷和泡泡','较差','在看的过程中我就很纳闷为什么这部的评价这么高，是因为是普通话版本影响还是我真的没那欣赏能力。','2011-01-31 20:25:34'),(3,'北影厂彪哥','推荐','张曼玉真是风骚啊','2006-02-18 12:04:59'),(4,'元宝宝','推荐','张曼玉将金镶玉风骚入骨敢恨敢爱的性格刻画的入木三分。林青霞和梁家辉亦将江湖儿女的情怀与抱负演绎的丝丝入扣。其它一众配角个个可圈可点，经典之作。','2017-03-20 16:03:35'),(5,'伊谢尔伦的风','推荐','梁家辉果然比李连杰好多了……','2012-01-08 20:12:53'),(6,'V','力荐','那时甄子丹还没出名，在演大反派，林青霞因为《东方不败》、梁家辉因为《情人》都红到爆，但该片的最大受益人却是张曼玉。那个风骚入骨的客栈老板娘，成了武侠影史上跳不过去的一页。今后恐怕没人能比张曼玉演江湖客栈里的老板娘演得更好了。','2009-03-28 20:04:41'),(7,'赱馬觀♣','推荐','本片素材来源之一的迎春阁本属于谍战卧底戏。店家双重身份但立场坚定任务明确。徐克只取其女老板和男伙计的角色构成，然后搁到老龙门救孤的故事架构中，并且有意放大了客栈的灰色属性，金镶玉不选边不介入两边通吃。这就使得新龙门更像瑞克酒吧。而在北非谍影的叙事体系中，瑞克是绝对核心，维克多立场固化爱情下风，双向偏弱。徐克不想如此。他习惯塑造三强点的爱情纠葛：周淮安必爱邱莫言，金镶玉只在自多情。可龙门客栈偏偏是她的主场！爱情失意，戏份充足，左右逢源。所以观众仍会觉得张曼玉很出风头。但通片最出风头的一定要交给最低调的那位。个人以为伙计剔骨取法影武者的火枪盲射士卒，小人物突然决定了大事件。不管是否联想太多，至少它遏制了传统武侠强强对决那种极度彪扬的气势，平添几分人算不如天算的黑色反讽意味，更贴合了九零时代思潮。','2019-09-05 04:02:05'),(8,'ᥫ᭡້໌','推荐','那个时候的审美就是风情之美，现在的审美感觉在下降。。','2017-02-17 18:46:05'),(9,'焚紙樓','还行','不似正邪之爭，而是無情（宦官）和有情人的對立，且是精神生理併行：周邱之間的男女之愛、邱金之間的女女曖昧、金周之間的性吸引力、以至孤人小二對喪父姊弟類似親情投射的情誼，再再都是沒陽具便不配有的關係。相較於劇外比劇內陣營還多還雜的洋片典故，這個安排倒是非常的「中國特色」，獨一無二啊。','2018-02-21 23:01:30'),(10,'少年夏不安','力荐','大漠孤烟直，长河落日圆。感觉这才是中国的西部片。茫茫大漠里一间小客栈里面各种势力的冲突纠葛。话说原来那双刀鞑子男才是扫地僧般的存在啊。','2010-11-04 15:09:02'),(11,'潇潇暮雨','推荐','经典啊，现在几乎没了啊这种纯正武侠风','2017-08-22 01:03:04'),(12,'(๑⁼̴̀д⁼̴́๑)','推荐','洞房花烛夜，楼上的周淮安与金镶玉各怀心事暗中较劲，楼下的邱莫言、贺虎等人也与东厂一众“走狗”展开了明争暗斗，战事一触即发','2017-08-21 22:56:20'),(13,'老鸡｜扶立','力荐','这部片子里面最帅的其实是小二','2008-01-10 17:07:55'),(14,'小耳朵图吗','推荐','徐老怪','2006-08-21 02:44:52'),(15,'轰小云@七汉字','力荐','三步一个青霞, 五步一个曼玉, 甚是享受','2008-05-24 20:45:58');
/*!40000 ALTER TABLE `新龙门客栈` ENABLE KEYS */;
UNLOCK TABLES;

