INSERT INTO `无耻混蛋` VALUES (1,'Minjie','力荐','昆汀的恋足癖还是藏不住啊。','2009-11-20 03:49:04'),(2,'JACK','力荐','冲着皮特和昆汀去的，结果被德国太保给迷住了','2009-12-08 09:27:24'),(3,'杜','推荐','当法国人不讲情义，美国人不讲人权，德国人不讲原则，英国人满脑浆糊，犹太人大开杀戒，希特勒就死了。','2009-11-21 11:29:08'),(4,'文森特的耳朵 | 生命短促啊','力荐','看到女主角对着镜头外的纳粹大笑，简直肾上腺素爆增啊。','2010-10-17 10:30:09'),(5,'猫小姐','还行','昆汀同学越来越变态了 ，比北野武还杜琪峰。','2009-08-23 10:21:27'),(6,'Ariza','还行','引用某影評人曾說的話：「一些得令的導演，由於創作泉源枯竭，只會從B級或C級垃圾片堆中覓食，美其名說向它們致敬，終究下過是垃圾再造垃圾而已。」','2009-08-21 00:24:31'),(7,'UrthónaD\'Mors','还行','这个片子的败笔是皮特，他怎么看怎么就像是个摆设连演插科打诨的皮条客都不像，最后那点太能YY了','2010-09-28 00:14:58'),(8,'大头绿豆','推荐','流畅，看起来毫不费力。除了布拉德皮特显得格格不入，除了地下酒吧那场居然不收拾现场有些BUG，除了绑着TNT居然能混进元首活动场所很无稽，其他都很好，很完整，完成了电影所能给出的最重要的功能：娱乐。','2010-07-26 10:40:58'),(9,'光年‖影视歌三栖民工','力荐','红衣女子因为恻隐之心送了命，是少数几个正常点的黑色幽默。。。','2009-11-20 23:13:15'),(10,'喵过留影','推荐','这部电影告诉我们：绝对不能相信美国人！','2009-12-03 12:14:34'),(11,'yuςii','力荐','天才這次拿出了歷史,以影史破壞影史,甚至燒毀影史,瓦解歷史,誓要引領影迷在面對歷史的同時要走出歷史.','2009-09-03 23:01:34'),(12,'桃桃林林','力荐','电影的魅力，他用电影创造历史','2009-11-23 16:07:24'),(13,'荞麦','推荐','重新看了一下开头：德国军官是如何在十分钟之内让一个大老爷们儿崩溃的。','2012-07-14 21:54:53'),(14,'Kennn.','力荐','Quentin是他媽的天才！','2009-05-27 06:16:21'),(15,'叶子风','还行','塔伦天伦回光反照之作。《杀死比尔》时奄奄一息的他，竟然还没死。片中有让人久违的怪鸡幽默，都通过愚蠢的对话表现出来的。这是他的招牌菜。其他的乏善可陈，割头皮是大败笔，黑色有余，幽默不足。','2009-09-24 10:02:58');
/*!40000 ALTER TABLE `无耻混蛋` ENABLE KEYS */;
UNLOCK TABLES;

