INSERT INTO `未麻的部屋` VALUES (1,'托尼·王大拿','力荐','达伦，你到底从今敏那里偷了多少灵感，这和《黑天鹅》的设定有很多相似之处啊！镜子的割裂，心理暗示，散碎的剪辑，真他妈牛逼。','2011-04-24 14:15:26'),(2,'老阿飞—故园','推荐','谁说今敏不牛b我跟谁急','2006-03-15 03:35:48'),(3,'易老邪','力荐','片子结尾将一切坐实为留美所为不能不说有丝遗憾，其实我个人更赞赏影片60多分钟时的那个剧情构思和说法，即，之前所发生的一切只是一个名叫高仓阳子的平凡女子的人格分裂，把自己幻想为偶像歌女雾越未麻，把自己不堪回首的遭遇幻想成在演戏，藉此得以解脱。','2010-11-02 23:06:44'),(4,'如花就是小妖','力荐','好的剧本就是就算你猜到了结局也猜不到全部','2009-12-15 13:50:33'),(5,'翻滚吧！蛋堡','力荐','看今敏解读，他自己提到《梦之安魂曲》里浴室镜头的模仿：“什么致敬，明明就是抄袭！那个坐在浴缸里的女主角就是詹妮弗·康纳利。后来我还和她坐过同一架飞机，结果她在头等舱，我在经济舱。”哈哈哈哈哈哈','2015-07-08 00:13:12'),(6,'昏金暗玉','力荐','想想看这才是1997年的动画电影！今时今日很多真人电影仍然无法比拟它的用心良苦、诚意、和所达到的效果。为了扑朔迷离，今敏用尽心思。','2010-08-15 15:41:59'),(7,'有未始有始也者','推荐','強姦戲可以理解，拍裸體寫真就絕對是敗筆（雖然是留美發瘋的關鍵），這樣一來未麻的演員定位就有問題了，到底是實力派呢？还是三級片明星呢？','2007-01-23 02:54:59'),(8,'Doublebitch','力荐','这绝逼不是给小孩子看的动画','2010-11-15 14:33:05'),(9,'同志亦凡人中文站','力荐','惊悚得头发梢都立起来了，今敏就是动画界的大卫·林奇啊！虚实切换得让人叹为观止～','2015-05-17 17:46:41'),(10,'JOJOORC/Z','推荐','边看边起鸡皮疙瘩，但看到结尾为什么觉得很励志……电影海报是神作','2007-05-28 00:02:22'),(11,'牧三洵','力荐','表现人物扭曲的方式：眼距加宽。','2022-11-24 13:08:50'),(12,'匡轶歌','力荐','这就是那种即便导演给有一个看似“封闭”了的结局，也依然完全“开放”的片子。任何一种诠释都可以成立，也都无法彻底成立。','2013-02-20 16:06:43'),(13,'Rivers','推荐','梦境 现实 虚幻 穆赫兰道的感觉','2010-10-11 09:57:03'),(14,'木由','力荐','最好看的今敏。一个细节，所有被杀的人都是被刺了眼睛。','2015-05-09 10:17:38'),(15,'汪金卫','力荐','今敏大师导演的第一部动画，原来就如此牛逼！与之相比《黑天鹅》简直如同一个拙劣的模仿者。人格的分裂，梦境、戏剧和现实的混淆如此诡异、出色，只有动画……不，只有今敏的动画才做得出来！凌厉的剪辑令80分钟里观众时刻紧张万分。不停的思考情节和人格的真假。浑身冒冷汗。黑天鹅弱爆了！//20180923SAME法文展映。时隔多年再刷，买了原画分镜设定集，又看了今 敏的书了解了制作的来龙去脉。在影厅里依旧看得头皮发麻。除了因制作问题在作画方面有瑕疵，在剧情、分镜、音乐上堪称完美。梦境与现实，真实与虚幻，人格分裂、戏中戏……环环相扣，大师处女作即展露出尖锐的锋芒，已能看到后来作品的影子//20240424北京电影节资料馆4K修复版。','2011-11-27 19:14:26');
/*!40000 ALTER TABLE `未麻的部屋` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `末代皇帝`
--

DROP TABLE IF EXISTS `末代皇帝`;
