INSERT INTO `末路狂花` VALUES (1,'七七|烂柯人bot','推荐','最大的败笔是警长啊是警长，她们并不需要来自男性世界貌似大公无私的救赎啊','2010-10-27 12:13:16'),(2,'战国客','推荐','“当一个女人说不要的时候，她是真的不愿意！”','2008-07-14 14:55:24'),(3,'荒野狷鱼','力荐','看到评论里有人说这是女人被激怒了，还让她们冷静点，实在让人无语。现实中的女人还不够冷静吗？如果凡是女人被骚扰被调戏被羞辱都像电影一样拔枪相向，不知道多少男人横死街头。哪还有你轻飘飘说句“冷静”的机会。电影没有给两位女主活路，本身就是说这样行不通，编导是用这个故事告诉我们，那些不尊重女性的男人多么的可憎，多么该死！如果这都看不明白，不是蠢，便是坏。','2021-06-17 17:25:42'),(4,'我爱面子不爱你','力荐','说实在话，这真是难得一见的几个稍微看得过眼的外国影片的中文译名之一……','2009-09-26 22:52:09'),(5,'阿依达','力荐','你知道有多少女人在被别人欺负。你又要知道有多少女人在独立，在反击。','2010-12-08 16:35:57'),(6,'眠去','推荐','这个结尾让我看得特别悲伤，在长久的短期内，这个世界这个社会仍然是男权的。','2008-05-14 12:26:09'),(7,'艾小柯','推荐','没有了退路，只好飞向自由。女性主义代表作。','2010-04-20 02:40:42'),(8,'莫不谷','力荐','希望说出“一个女的如果答应跟一个男的单独吃饭单独看电影，就是答应跟这个男的上床了”这句话的韩寒和持有同样想法的男性可以看看这部电影，它里面的每一发子弹都是射向你们的。她们为什么要逃，以及为什么逃不脱，都是时至今日女性仍然面临的系统性的困境。末路狂花的飞车坠崖，和玉娇龙的纵身一跃，都是被压迫的生命最激烈的反抗和自由的抉择。','2022-01-14 20:27:40'),(9,'carmen','力荐','枪是阳具的隐喻 只有女人有枪才能完成犯罪 说和女权女性觉醒无关的大概真的没看懂 安塞尔说i just cant live.时我就知道结局 结尾是那样的自由，注定鸟不属于父权的监牢 那个想保护女孩的警长特别像父权制下表现的爱护你但他无法冲破系统禁锢的男性。他认为这些女孩是善良的一切都是被逼的。如果我是导演，我会让她们射杀那个公路卡车司机，而不是惩戒他只是打爆他的车。刻板印象中男性是可能做出这样的事的。女性的善良难道不是一种规训？为什么少有连环变态女杀手的电影，以猎杀男性为乐？','2021-08-18 23:15:24'),(10,'A-sun*','推荐','Thelma开头差点没气死我，不知道吃一堑长一智，骚情满溢地再被Brad Pitt勾搭，全忘了曾被强暴。Louise则是我喜爱的型，不后悔不责备勇担当，但后来角色转变却有着微妙的互换，Thelma果断与明快了起来这里很巧妙。尽管设定两人走向一条不归路，但依然很喜欢安排了警官这角色','2010-06-13 21:09:17'),(11,'熊大柚小內內','力荐','请原谅我土鳖了现在才看过这片，但我觉得特别特别好看！！！！！！！！','2010-04-05 04:20:19'),(12,'王神爱','力荐','最后警察包围她们的时候说“任何不服从指令的行为，将视为对我们的挑衅” 这其实也是很多男人对女人的潜意识','2011-09-18 05:10:21'),(13,'宝钗洛克哈特','力荐','在唐山案的第二日看。电影与现实产生了许多互文：女性要如何反抗性暴力才不会使自己受伤？答案是一致的——不可能。要么是杀死对方，自己踏上逃亡的不归路，只能在悬崖一跃，追求最终的自由；要么是被男人残忍击打，倒在暗黑中。只有女性情谊才是这个疯狂世界的唯一救赎。30年过去了，一切都没有改变。','2022-06-11 20:43:24'),(14,'Little Punk','无评分','heaven\'s drive.最后一刻，我是笑着的，却分明流下了眼泪','2006-11-28 11:42:50'),(15,'路人X','推荐','这其实不是女权电影','2005-07-08 03:35:13');
/*!40000 ALTER TABLE `末路狂花` ENABLE KEYS */;
UNLOCK TABLES;

