/*!40000 ALTER TABLE `海边的曼彻斯特` DISABLE KEYS */;
INSERT INTO `海边的曼彻斯特` VALUES (1,'哪吒男','力荐','我和我不想要的后半生，我和我不愿意和解的自己。你们都朝春天去，就留我在破碎里又丧又美丽。','2017-01-25 14:34:11'),(2,'k','推荐','那些劝我们向前看的朋友，“不是所有人都可以和过去和解”','2017-01-25 23:52:52'),(3,'荞麦','还行','……就还好啊。怎么大家集体爱上这种了？','2017-01-28 03:20:50'),(4,'根','推荐','人生的伤口，二十五岁之前怪父母，二十五岁之后怪社会，最惨就是巨大伤口摊开在那里，腐臭流脓永不愈合，然而，无人可怪','2017-02-20 10:07:48'),(5,'陀螺凡达可','推荐','又名《回忆杀》。有遗憾和失望，二刷后感觉对角色的好感甚于电影，卡西的角色写得演得太饱满了，让我对这个角色产生了依恋感。','2016-12-14 06:09:43'),(6,'桃桃林林','推荐','生活流，如何绕过苦难，丧到骨子里的卡西，绕不过去的苦难。','2017-02-16 19:11:00'),(7,'丁一','无评分','君自海边来， 不提故乡事， 独返雪故乡， 不愿见来人， 近乡情更怯， 无味已多时， 经冬复历春， 不治亦不愈','2017-02-28 08:57:33'),(8,'品客','推荐','最后乔在帮老人修锅炉时，老人说自己的父亲在95年出海突然消失。看似突兀的这场戏其实也是电影的主题：世事无常的生活不过只是一成不变的插曲，日子始终在继续，渔民依然每天出海，候鸟迁徙南飞，乔还是乔。','2017-02-02 15:40:19'),(9,'Saltsalt726','力荐','有時關不上冰箱的門 腳趾撞到了桌腿 臨出門找不到手機 嚎啕大哭 你覺得小題大作 只有我自己知道為什麼','2017-02-02 20:41:35'),(10,'米粒','推荐','典型的“中产阶级伤痛故事”通过穿插的剪辑打碎了压抑的情绪，喜忧参半的剧本看得出非常花心思，不是暖心的鸡汤，也没有让人沉浸在心碎中，度把握得很好，两个多小时不显漫长。而且算是卡西的独角戏了！他真是个气质独特的演员，没有所谓的“夺金时刻”，却把情绪慢慢渗透到了每一个镜头里','2016-10-03 12:20:32'),(11,'Meng','推荐','音乐略满，阿弗莱克妥妥的影帝提名；作者应该受过女性伤害，女性角色都有点怪。','2016-09-17 11:34:05'),(12,'欢乐分裂','推荐','破碎的我怎么拯救破碎的你，阴冷肃杀的冬日海边，冷意钻入骨子无可避退，人生中的低谷寒潮已无可能褪去，不如全力拥抱破碎的自己；多处人物台词重重叠叠，我们从未打算走入他人生活，只愿守住自己的孤岛，沉沦在自己的泥淖。','2017-02-09 23:35:59'),(13,'LORENZO 洛伦佐','推荐','四星半。如果被生活判了死刑，还有什么值得留恋？一场死亡揭开了旧伤，也把最暖的亲情带到面前。细碎的拥抱和拍抚，像零星的火种，终于点燃了男主的心中余烬。即便他心里藏着全世界的冰雪，那也会慢慢溶解，丧门星也会有春天。凯西表演冷静震撼直让人心痛心怜，用幽默外壳下的重度悲伤直指人心。','2017-01-18 07:37:01'),(14,'亵渎电影','推荐','这几年奥斯卡颁奖季不错的电影，剧本都不能用麦基的《故事》来判断好坏了，《海边的曼彻斯特》就是，从那套“好”剧本的标准看李这个人物，它的塑造方式犯大忌，但作为生活流的故事，正是这些所谓的“坏”让这个故事变得不一样，有了一种新鲜的感觉，李这个人物的丧和悲伤反而变得不狗血，更生活了。','2017-02-03 20:14:00'),(15,'樹一','推荐','2017年看的第一部电影，是一个人在Williamsburg的一家小影院看完的。因为是午夜场，无字幕，昏睡了一半的时间，几近绝望且漫长的两小时，即便是这样，在散场之后也清晰记住了几个异常凌冽的孤独片段，在电影里看到了比自己更惨的人生，也没有得到释怀，淋着雨走回了公寓。','2017-01-06 15:01:25');
/*!40000 ALTER TABLE `海边的曼彻斯特` ENABLE KEYS */;
UNLOCK TABLES;

