INSERT INTO `源代码` VALUES (1,'denovo','力荐','这部电影告诉我们，最重要的不是想出一套没有硬伤的“科幻”元素，而是讲一个好故事。','2011-04-16 20:05:25'),(2,'seren','推荐','平行世界理论一定是真的，我坚定不移的相信着','2011-04-08 07:09:01'),(3,'D I D A','力荐','竟然看到短评里有人言“结局累赘”、“如果一切停在这个吻就完美了”。卧槽，两位琼瑶剧迷请勿玷污科幻电影的SF之神好么！！！！可以说，影片3/4之前的剧情是立意新颖但仍中规中矩的悬疑惊悚片，但是结尾处的1/4剧情简直达到了科幻电影的肾上腺素暴表线。这个结局甚至比《月球》更加悬幻陡峭.','2011-07-19 01:04:03'),(4,'易老邪','推荐','居然有那么多人认为《源代码》最完美的结局应该是定格在最后那一吻上，由此可见，真要这样结尾够有多么的恶俗不堪啊。','2011-07-13 20:26:27'),(5,'ParasItE','推荐','如果结局停在那一吻我就给四星半了。','2011-04-03 13:19:30'),(6,'砒霜拌飯','推荐','太憋屈了，不是太空舱就是火车厢，幸好他最后出去了，要不得憋死我','2011-06-19 23:04:49'),(7,'vin','推荐','最后3分钟有点画蛇添足。','2011-04-02 04:53:06'),(8,'makzhou','推荐','不赖，但是看着没什么心潮澎湃的感觉，激动不起来','2011-04-06 09:43:41'),(9,'画下天籁','力荐','还好结局不是停在最后那一吻上，否则我给不了五颗星。希望在美好时停住，其实是内心脆弱的表现。从美好开始，延续下去，才饱含未来充满的坚强和希望的力量。谁的人生没有遗憾？但你要相信，在另一个世界，那些遗憾会被弥补。','2011-06-28 19:42:33'),(10,'玎老师大声疾呼','推荐','全片最喜欢的片段是，从古德温角度看男主只是文字。不知道为啥很戳我泪点','2022-02-12 22:45:22'),(11,'tower','力荐','如果画面停在最后一吻上,就完美了.','2011-04-05 03:02:50'),(12,'大奇特(Grinch)','推荐','Inception+Groundhog Day，现实和记忆是相辅相成的，只要能生存的有意义管它是哪里，何况这本身就是一个平行宇宙。结尾定格在静止画面时才是真正完美的结局，之后几分钟剧情完全可以忽视。','2011-04-20 23:22:10'),(13,'路上','推荐','这才是货真价值的穿越大作！','2011-04-28 21:42:01'),(14,'等一个人','力荐','牛B的本子，邓肯·琼斯没有淹没在好莱坞的体制中，继处女作《月球》之后再度奉献出一部精彩绝伦的科幻作品，唯一的遗憾就是在技术层面给出的解释不够充实，结尾稍显多余。','2011-04-19 15:42:16'),(15,'A L E X','力荐','很久没有看这种结构的电影了，所有一切都很赞，而立之年的Jake更多了一份稳重内敛，碧蓝的双眼温暖至极。最后看哭了。i\'m asking you,just send me back in, then switch me off. Everything is gonna be OK.','2011-04-07 11:57:54');
/*!40000 ALTER TABLE `源代码` ENABLE KEYS */;
UNLOCK TABLES;

