INSERT INTO `狮子王` VALUES (1,'罗弘霉素','推荐','败在“刀疤”没有反派魅力！','2010-07-08 18:09:30'),(2,'影志','力荐','“太阳所能照到的地方，都是我们的国土” 随时随地、再看百遍、都会感动如初的经典。','2005-08-24 07:19:46'),(3,'Kaito','力荐','hakunamatata','2006-05-13 08:01:49'),(4,'铃铛','推荐','我只是在必要的时候才会勇敢，勇敢并不代表你要到处闯祸。','2018-04-25 16:06:49'),(5,'寒 汐','力荐','动物版哈姆雷特','2008-02-02 12:03:44'),(6,'伍德与夏洛蒂','力荐','最爱的迪士尼，没有之一。','2011-03-16 20:44:17'),(7,'股神看不懂','力荐','经典之所以称之为经典正是因为他无法复制，狮子王就是这样的经典，每一个细节都那么出色，每个音乐都那么动听，恰到好处的搞笑和贯彻始终的感动。这样的片子不管放到什么时候都不会落伍，因为他本身就是传奇','2016-11-02 22:31:06'),(8,'lostcat','力荐','经典得都烂了','2009-08-05 13:46:26'),(9,'TORO VAN DARKO','力荐','又是一部是属于那个年代的影迷的经典','2008-10-04 03:44:04'),(10,'同志亦凡人中文站','推荐','现在看剧情真的好简单啊，不过拟人感实在太完美了。还有那个“哈库那莫塔塔”，好多年没听到了...Can You Feel My Love Tonight？','2012-10-28 18:47:54'),(11,'炫3D','力荐','这部动画绝对是经典，内容积极向上，音乐无可挑剔。','2017-03-22 11:18:42'),(12,'吃瓜小能手','力荐','勇气与成长的故事，即使过了多少年，即使生处不同的时代，仍旧能够让人有所感悟……辛巴是在波折的人生中踏出了那条成王的道路！','2017-04-12 19:52:36'),(13,'老鸡｜扶立','推荐','从此得知，原来动画片还可以是这样的……','2008-01-10 16:46:34'),(14,'遇见彩虹?','力荐','应该是我看过的第一部迪士尼动画电影，还是看的英文版的，绝大部分句子没听懂，光看画面当年就觉得很惊艳！','2017-11-10 14:25:06'),(15,'托尼·王大拿','力荐','重看，这一部当是Disney Classics的集大成之作了，汉斯·季默、埃尔顿·约翰联手为其锦上添花；另外个中暗含的隐喻也很值得玩味：刀疤在鬣狗领土密谋造反后检阅那场戏，简直就是照着《意志的胜利》扒下来的，哈哈。','2018-09-10 04:27:22');
/*!40000 ALTER TABLE `狮子王` ENABLE KEYS */;
UNLOCK TABLES;

