INSERT INTO `玛丽和麦克斯` VALUES (1,'二甲','力荐','个人认为影片比《飞屋环游记》要出色','2009-10-27 20:30:08'),(2,'阿北','推荐','伤心电影，好电影。结尾告诉我们，网友见面要早。','2009-12-02 23:02:50'),(3,'披着人皮的鬼','推荐','拍电影是不是和做爱一样 只有技术做不出感情','2009-11-12 23:33:46'),(4,'Doublebitch','力荐','年轻时我想变成任何人除了自己。','2009-11-02 19:14:18'),(5,'mayfly','力荐','PS,娘的，我看哭了。PPS,推荐给所有的人看。PPPS,可以打十星吗？','2009-11-16 18:54:13'),(6,'sasasasa','力荐','我们为什么需要3D？','2009-10-27 19:18:06'),(7,'陌生人','力荐','God gave us our relatives, thank god we can choose our friends.','2009-10-01 03:17:26'),(8,'指梦为马','力荐','谁脱了衣服没几道伤疤','2009-10-27 00:10:15'),(9,'匡轶歌','推荐','当我年轻的时候，我想变成任何一个人，除了我自己。伯纳德医生说：我必须要接受我自己，我的缺点和全部。我们无法选择我们的缺点，它们也是我们的一部分，我们必须适应它们。然而，我们能选择我们的朋友，我很高兴选择了你。','2009-12-11 15:27:38'),(10,'陈问问','较差','这两颗星我给的是黏土技术','2009-11-16 09:42:40'),(11,'匿名的宝贝♥','力荐','不是只有完美的人，才配爱自己。要知道，完美不存在于这个世界。','2009-10-26 22:38:14'),(12,'卡比巴拉的海','还行','你是我最好的朋友，你是我唯一的朋友','2017-04-07 14:53:37'),(13,'蚂蚁没问题','力荐','每个人都不完美，每个人的人生也总是不完美的，这不是一部迪斯尼电影，所以不会有Happily ever after。一部动画深刻到这步田地，我挺佩服的，挺喜欢的，其实自己也会有那么一时三刻很像Mary也像Max，自卑焦虑又孤独又低落，倒霉的事儿有时也发生，所以有点懂有点感动.','2009-10-28 23:06:17'),(14,'草威','力荐','我一直不明白一个问题，有趣是不是源于自卑和寂寞？','2012-08-31 23:31:59'),(15,'扭腰客','力荐','只有宇宙和人类的寂寞是永恒的','2009-11-27 02:05:56');
/*!40000 ALTER TABLE `玛丽和麦克斯` ENABLE KEYS */;
UNLOCK TABLES;

