/*!40000 ALTER TABLE `玩具总动员3` DISABLE KEYS */;
INSERT INTO `玩具总动员3` VALUES (1,'荔枝超人','推荐','闪耀着万丈光芒的又一动画杰作。每一处笑点都能轻易抓到，让我就像是回到了15年前，开心到得意忘形。最后一场戏动人程度堪比UP的\"married life\"!','2010-06-12 21:18:22'),(2,'猪是的念来过倒','力荐','我87年出生，，看toy 1是小学3年级。看toy3是大学毕业。纯爷们，没哭死我。。。。我想说 这是皮克斯送给我们这代人的一份礼物。再见了，我的童年，谢谢你，皮克斯','2010-06-16 22:12:00'),(3,'Q。','推荐','它对于我已经不仅仅是一部电影那么简单，而是代表了对于童年时代的记忆与怀念，整个电影院从头到尾笑声不断，但我相信，更多人会被影片的后半段打动，相信看过前两部的人都会很感慨。★★★★☆','2010-06-25 00:40:06'),(4,'ｄａｂａｉ','力荐','玩具总动员3的感人之处就是帮我们这些老家伙给了一个正式的和童年say goodbye的机会，当上大学的andy再一次背起woody的时候，十五年的光阴就这么友好又温柔地消失在木栅屋远处的夕阳中了。','2010-06-16 02:00:01'),(5,'桃桃林林','推荐','还记得你的那些玩伴么？','2010-08-15 09:38:40'),(6,'Neroat','推荐','个人觉得比一二部要好，没想到最后温馨动人得我差点眼眶都要红了。17岁的青少年不玩玩具啦，尽管如此还是替玩具找到了好的归宿，“被人玩”才是玩具存在的意义啊，给我压箱底的娃娃说句对不起。','2018-08-06 23:18:47'),(7,'亵渎电影','推荐','从感性的角度看这部【玩3】，它太完美了，但从理性的角度来讲，类似Roger Ebert这类牛逼影评人和媒体不怎么买账也是正常的。试想一下，很简单，【WALL-E】和【UP】这类电影为什么皮克斯打死不准备去续集，而【玩】系列到了第三部？★★★','2010-06-22 10:35:14'),(8,'辣辣的皮特','还行','感觉很平淡呀，难道童心离我而去了吗？no...另外，3D效果不如驯龙高手。','2010-06-16 12:02:25'),(9,'影子的影子','力荐','前半部分就有好几次想哭的冲动，本来以为这次能够幸免的，没想到最后几分钟那么煽情，简直要哭死了。其实3D效果并没有很出色，但是精彩的剧本真的很让人感动。这不是一部给小孩子的动画，是一部给成人的童话。','2010-06-11 06:36:18'),(10,'山人阿苍苍','力荐','让我笑已经够了，居然还能让我哭，nice job！','2010-06-12 19:56:06'),(11,'皮皮','推荐','把我看哭了，还真觉得玩具也是有生命的了。','2018-02-14 23:28:33'),(12,'根','推荐','小孩子看了做一辈子噩梦','2017-12-19 23:46:37'),(13,'锡罐头','力荐','1.前一个多小时充分照顾了片子的趣味探险气质，后半个小时照顾了跨度十多年的老观众，真让人情到深处，潸然泪下！2.玩具们的最好归宿到底是哪？本片探讨的问题其实已经超越了前两部，整体性上也兼顾的很好，如果这是完结片，的确相当不错！','2010-06-16 15:31:04'),(14,'同志亦凡人中文站','力荐','结尾的煽情很见水准，但现实中哪里还找得到Andy这样单纯童真的17岁少年呢？！','2010-06-17 09:57:31'),(15,'郭朋克','力荐','跨度十五年的欢乐与泪水','2010-06-16 21:04:06');
/*!40000 ALTER TABLE `玩具总动员3` ENABLE KEYS */;
UNLOCK TABLES;

