INSERT INTO `甜蜜蜜` VALUES (1,'瓜。相信这个世界很变态。','还行','其实是曾志伟的角色最令我动容。','2008-08-09 21:31:19'),(2,'Ragdoll™','力荐','你什么时候变得这么罗嗦，以前都不是这样，傻女，听我说，现在立刻回家，洗个热水澡，明早起来，满街都有男人，个个都比豹哥好。不用担心，我很有办法的，在台湾有很多老婆，高雄有一个，台中有一个，花莲有一个，阿里山也有一个…… \\\\\\\\我这辈子最开心的那一天，就是威廉带我去半岛吃饭，我趁着他不留意，偷了我们用过的刀叉杯碟，现在偶尔拿出来看一下，仍然是很开心，可能威廉早就不记得我了，不过不要紧，我记得就行了，想一下，我现在这么老这么难看，他不来找我其实都是好的。\\\\\\哈，那你要快点，芥兰有艾滋。','2009-05-18 18:00:48'),(3,'王xx','力荐','每次看完这种片子，都觉得像过了一辈子那么长','2009-01-06 19:07:26'),(4,'Megan','推荐','你们看到了爱情，我看到了背叛。','2011-01-05 10:44:33'),(5,'小儿勾','力荐','其实我是被米老鼠感动的','2007-01-17 13:31:10'),(6,'王大盆','推荐','傻女，听我说，现在立刻回家，洗个热水澡，明早起来，满街都有男人，个个都比豹哥好。','2013-07-12 00:39:48'),(7,'mu','力荐','重逢只要一瞬间，等待却像是一辈子。','2010-10-29 19:00:19'),(8,'弗朗索瓦张。','推荐','这么多人都看哭了么。。。我就在张曼玉低头碰到喇叭那块儿眼红了下。。。这俩人的缘分太让人嫉妒了','2009-12-18 14:43:25'),(9,'drunkdoggy','力荐','“我不是文艺片导演，这是部十足的商业片，结尾纯粹为讨好观众而设计。现实中，男女主人公不可能在一起。但观众想要他们在一起。其实呢，如果他们能在一起，早在一起了。”我们怎么办啊……','2014-09-10 22:45:39'),(10,'丁小云','力荐','因为一直不怎么喜欢黎明演的戏，所以隔了这么多年，刚刚才看了《甜蜜蜜》这部电影，真好看啊，这才是真正的爱情电影啊……在短短一部电影中竟能拍出百转千回的感觉，看得我眼泪都流干了……缘来如此艰难，缘来如此美妙……不可不信缘……唉，要回到现实中了，晚饭吃什么呢……','2011-03-08 17:56:34'),(11,'影志','力荐','This is not so much a story about people falling in love, but rather of two young heart trying their best not to fall in love with each other.','2005-07-22 01:26:58'),(12,'今天小熊不吃糖','力荐','“我今天带了个朋友来，听说你很怕他……”——如果是我，我也会选豹哥。在昏昏噩噩之中，我们错过了多少，又真正得到了什么……','2009-02-22 00:54:37'),(13,'郁殷','推荐','曾经的香港电影多么令人激动与感动。','2009-07-30 23:17:28'),(14,'Miss Lucky','无评分','随性,就是用滑过的火柴当眉笔','2006-12-22 20:35:39'),(15,'LOOK','推荐','张曼玉精彩绝伦的演出成就了这部电影。聚散离合，缘起缘灭，情感的纹理与能量、生成与幻灭、真挚与虚妄，历史的荒诞与无情，一切的一切都是张曼玉。情到深处爆发出来的能量，如花瞬间绽放，充沛又从容，亚洲女星中大概唯有巅峰年代的高峰秀子可与之比肩。','2017-03-05 21:42:27');
/*!40000 ALTER TABLE `甜蜜蜜` ENABLE KEYS */;
UNLOCK TABLES;

