INSERT INTO `电锯惊魂` VALUES (1,'青菜萝卜和豆腐','推荐','为嘛医生不用锯子够手机？','2010-01-30 14:29:38'),(2,'毛','推荐','可是跟电锯有毛线关系啊 明明是手动的','2010-12-07 21:31:42'),(3,'Ridden','力荐','最后五分钟让我全身发抖！','2007-11-09 23:35:22'),(4,'王xx','无评分','如果一开始够不到那个东西人家老头可不要急死了','2010-03-19 21:12:44'),(5,'晨光荣耀','推荐','最终boss躺着不累吗？？','2009-03-09 23:35:00'),(6,'是灰小猫啊','力荐','这其实是个励志片好不好，杀手先生告诉俺们即使在生命的尽头还是能干成很多事情滴~','2010-10-21 21:53:51'),(7,'有心打扰','力荐','当那躺在地上一动不动的那个人站起来后，我就彻底震惊了。','2010-04-19 12:33:30'),(8,'satan','推荐','有些疑问。医生为什么不用电锯把手机勾回来。。。而是选择锯腿。。。他老婆一直在打电话，但是为什么后来密室里的电话不再响了？','2011-02-12 16:33:51'),(9,'范小奚','力荐','看第一部的时候着实被他的情节设计给惊讶到了。','2008-07-21 12:46:09'),(10,'束','力荐','第二次看，感觉着仍然是一部顶级的血腥电影，结构和叙事都很牛逼，叙事张弛有度。','2006-01-24 04:05:59'),(11,'远子','还行','没有想象中的恐怖。恐怖的是，片子快结束的时候，我住处厨房的天花板塌了，噼里啪啦的，酱油瓶打碎泼了一地。拖地的时候，忽然想，这黑乎乎的一片好像人血啊……','2016-07-13 01:31:07'),(12,'任小可051','力荐','他喜欢近距离观察受害人，这个结局直接满分。','2021-05-09 22:32:07'),(13,'Elinor','推荐','这么多年了 没看之前我一直以为这片子是讲一个拿着电锯的杀人狂的故事...另外 我也终于明白了为什么豆瓣要改版把论坛话题隐藏 是为了防止我们看到剧透啊！！（那个剧透的人去死去死）','2010-11-11 21:59:14'),(14,'匡轶歌','还行','这真的是恐怖片吗，不好意思看得直笑场。警探蠢到简直有萌感，医生为毛不用锯子或衬衫够手机？医生老婆夺枪之后为毛不麻溜的pia pia两枪把坏人撂倒？还有这译名，电锯在哪儿？在，逗，我。','2015-07-08 20:33:27'),(15,'杨迪','力荐','警察是不是傻？？？','2018-02-16 15:58:22');
/*!40000 ALTER TABLE `电锯惊魂` ENABLE KEYS */;
UNLOCK TABLES;

