/*!40000 ALTER TABLE `真爱至上` DISABLE KEYS */;
INSERT INTO `真爱至上` VALUES (1,'大头绿豆','推荐','1、每当我对世局倍感忧虑时，就会想到希思罗机场的入境闸口。人们认为世界充满仇恨与贪婪，但我却不同意。在我看来爱无处不在，虽然未必来的轰轰烈烈，但是爱永远存在。父子，母女，夫妻，男朋友，女朋友，老朋友，当飞机撞上世贸大厦时，临终打出的电话，谈的不是报复，而都是爱。如果你肯留意，你会发现爱其实无处不在。love actually is all around.','2006-10-14 13:04:58'),(2,'大灰狼','推荐','至少能干掉几十部《全城热恋》吧','2011-02-25 10:27:40'),(3,'UglyBerry','无评分','我最期待的那一对没有走到一起。','2011-01-07 10:13:20'),(4,'卢十四','推荐','像我这样一个对外国电影了解不多的观众，看的时候一直处于“我靠这个人好眼熟，这个人不是那个谁吗，这个人是大牌吧，这个人我知道名字！……”的状态中。','2015-02-25 12:14:57'),(5,'同志亦凡人中文站','还行','上至正太下至首相都在谈恋爱，单身狗不配过圣诞。剧情什么的都是浮云了，我就看看演员～ (@﹏@)','2016-12-28 01:38:13'),(6,'奎斯Chris','推荐','我不明白,如果导演早就决定给个皆大欢喜的结局,为什么又不给得彻底点呢?','2007-05-25 02:57:11'),(7,'朝暮雪','推荐','“这是我一天当中最欢喜的时候，载着你。”“这是我一天当中最痛苦的时候，离开你。”','2016-12-22 11:14:07'),(8,'刘康康','推荐','可以称之为浪漫爱情片俗套桥段大全，但看完之后，心里面就是暖暖地充满正能量，哥们儿就喜欢俗的！爱上好朋友老婆那个故事，最后圣诞夜告白的段落拍得真是感动死了！','2013-01-08 15:16:43'),(9,'亵渎电影','力荐','我的圣诞必备，年年都是看这个，年年心情大不同，有时候一个人，有时候两个人，有时候一群人，今晚又是一个人，心里偶尔想着另一个人，偶尔想着一群人。★★★★★','2011-12-24 23:48:55'),(10,'Odding','还行','其实没什么情节。','2009-04-30 13:17:47'),(11,'屾叨','推荐','爱，是个动词！','2010-11-05 03:17:12'),(12,'海心','力荐','从头哭到尾，心里暖，而遍体生寒，寂寞无处隐身，生生将我蚕食。','2008-10-30 22:06:53'),(13,'熊✌?','还行','下了两年以后才开始看……看了半年都没看完……','2012-01-30 02:45:44'),(14,'不吃药药','推荐','那个英国老牌演员演的歌手很NB','2008-05-01 21:20:57'),(15,'沉歌','力荐','寂寞的圣诞夜一个人看这种电影，看完觉得更寂寞了！','2010-12-25 18:19:39');
/*!40000 ALTER TABLE `真爱至上` ENABLE KEYS */;
UNLOCK TABLES;

