INSERT INTO `纵横四海` VALUES (1,'木卫二','还行','有些电影，就该在那个时代看……','2006-08-13 18:51:51'),(2,'战国客','力荐','香港浪漫主义警匪动作片的巅峰之作！那段发哥和红姑的轮椅舞堪称香港电影史上的经典镜头~~','2007-06-24 10:28:16'),(3,'闲人','还行','套在枪战片外壳下的偷盗片，如果不是演员不会如此成功，反类型了，试问盗贼都能杀将出去，要偷技何用。','2010-05-13 11:59:58'),(4,'石头星','力荐','看过多遍，完全被三个人特有的自身魅力迷住，张国荣用红酒越红外线、三个人的舞蹈，至今都是经典。还有，发哥说，伊拉克不打仗。那是91年。','2017-03-26 21:20:20'),(5,'伊卡洛斯','推荐','你们都知道我的性格，我喜欢西逛逛，东逛逛，我喜欢流浪，其实爱一个人并不是要跟她一辈子的，我喜欢花， 难道我摘下来你让我闻闻，我喜欢风，难道你让风停下来，我喜欢云，难道你就让云罩着我，我喜欢海，难道我去跳海？','2011-03-23 23:04:09'),(6,'无条件积极关注','还行','这个本子，放到现代换三个流量演员演，妥妥的大烂片','2020-12-03 23:48:26'),(7,'高歌','力荐','优雅——除了这两个字，我不知道怎样表达对他们的爱慕之情啦。','2009-12-20 21:50:01'),(8,'九尾黑猫','力荐','经典就是经典，看无数遍也是经典','2008-03-10 14:39:06'),(9,'鸿音','力荐','因为去过巴黎，就更能感到张国荣站在塞纳河上吹风然后潇洒远去的风流，那种气质真是让人倾倒。发哥很多表演细节很风骚，太搞笑了。红姑还是那么美，绝代风华。','2016-11-09 09:04:11'),(10,'Connie','力荐','我常不自量力地寧願gorgor一直活在那兩年','2006-01-18 18:30:55'),(11,'胤祥','还行','倒不是因为年代问题，实在是后半部影片回了香港就各种崩坏而导致完全欣赏不能。感觉演员们到了后半段也完全不相信剧情了。很多动作设计到今天看也很有想法（但是细节上能更认真点吗？）值得一说的是剧作上“小三口儿”这个事儿竟然没解决……实在……比里面各种“间离”手法还要有趣得紧。','2017-11-07 02:03:46'),(12,'曼仔','力荐','当真是意气风发。我原本以为我不会喜欢周润发的，但是现在真是觉得，他的滑稽潇洒确实有魅力。张国荣自是眼角眉梢皆是温柔不羁。一曲风继续吹，真是有深情风流意。那时是港片的黄金时代啊，盛世青春。','2013-08-22 06:11:20'),(13,'晚凉天净','力荐','一部美不胜收的童话，有最令人心动的乌托邦式的爱情和友谊，最经典的三人组合。是一个不安、困惑、喧嚣却仍然纯粹而理想化的历史分期留给我们的礼物。西方古典绘画的介入有升华和纯粹化的作用。心情不好的时候最可以拿出来看，缅怀80-90年代的时候也可以看，想念哥哥的时候还是可以看。','2013-09-21 23:58:20'),(14,'晚不安','力荐','胶片重看。有情有义，游戏人间。尽管画面存在抖动、刮痕、过暗诸多问题，但仍得以辨认出这是吴宇森巅峰时期的巅峰之作。继续贯彻浪漫主义暴力美学的同时，用层出不穷的喜剧元素提升娱乐性并自我嘲解，还用东方的智慧解决《祖与占》式的三角关系（片中人物名字即在致敬这部法国新浪潮经典之作）。一句“祝你们春梦了无痕”潇洒至极，这三人行的组合无论在当时还是现在都是风华绝代。喜欢花，喜欢风，喜欢云，更喜欢不羁和自由。','2018-09-09 23:02:10'),(15,'眠去','推荐','香港影史最赞三人行','2007-02-25 10:00:02');
/*!40000 ALTER TABLE `纵横四海` ENABLE KEYS */;
UNLOCK TABLES;

