INSERT INTO `终结者2_审判日` VALUES (1,'唐小糖·','无评分','看这个我也能看哭，我多感性啊·','2009-06-03 16:17:30'),(2,'Dr.Moth','力荐','伙计们~还有什么比这个更棒的?','2008-07-05 07:55:43'),(3,'小海','力荐','这是在1991年啊，重复，这是在1991年啊！','2016-03-16 22:49:56'),(4,'陳','无评分','小時候覺得好帥','2009-01-05 00:13:21'),(5,'战国客','推荐','少见的超越首部的续集，动作片中的经典~~','2008-06-24 22:27:48'),(6,'Nakedself','力荐','金属狂躁！！！T1000的空前绝后在于一个机器人居然真的具有妖气。','2006-05-17 16:02:10'),(7,'朝暮雪','力荐','影史少见的第一部就足够经典，续集还能超越第一部的电影。 《终结者1》中，约翰·康纳将里斯传送到过去； 里斯又和莎拉·康纳生下约翰·康纳，形成一个闭环。 《终结者2》也是如此，正是天网将T-800传送到过去，才让人类得到终结者的芯片，从而得到灵感发明了天网，互为因果。 所以他们要找到迈尔斯·戴森，打破这个循环。 迈尔斯·戴森在平行宇宙是发明天网、间接毁灭世界的罪魁祸首，在这个宇宙却成了以生命为代价保护人类的英雄。 约翰·康纳对母亲的态度的转变也让人感触颇深。 他一直以为母亲是疯子，是失败者。 直到有一天，他发现母亲说的一切都是真的。 天网将T-800的中央处理器设为只读，防止他产生思想。 这样一个没有感情的杀手，竟然愿意通过终结自己，换来世界和平。 谁说机器不能有人性？ 烈焰中竖起大拇指的镜头堪称影史最震撼瞬间之一。','2012-08-18 02:03:39'),(8,'天蝎小猪','力荐','终结者三部曲中最经典的一部','2007-09-13 17:03:10'),(9,'多看电影爱电影','还行','施瓦辛格太酷了！','2017-03-22 08:19:02'),(10,'xjxiidjsns','力荐','I\'ll be back','2008-10-20 10:23:09'),(11,'souvent','还行','论大脑T2真的太幼齿了，简直把观众都当无脑儿：未来世界的军事领袖竟然教育T800不要随便杀人。没有比这更好笑的笑话了，我看到那里差点笑岔气。虽然阿诺的形象，还有他和液态机器人的对抗还是相当赞的。','2007-12-23 22:51:00'),(12,'冰红深蓝','力荐','詹姆斯卡梅隆的巅峰之作,永远的科幻经典。1.传统模型和化妆特效为主，电脑CG为辅；2.创意十足的最强反派：T-1000；3.施瓦辛格最好的表演；4.兼具动作片的爽快、科幻片的气魄与哲思、喜剧片的爆笑和文艺片的温情；5.机器人学习情感,以机器反思人性,揭示人的自毁倾向；6.\"点赞\"一幕至为感人。（9.5/10）','2015-06-09 17:36:42'),(13,'托尼·王大拿','力荐','宿命的终结，伟大不仅在于超越时代的特效。','2010-10-10 17:15:45'),(14,'vivien','还行','看终结者系列也算怀旧了。施瓦辛格当州长前真健美肌肉都像假的一样演机器人太合适了又不要演技也没表情。叛逆的小家伙实在和当年leo在成长烦恼里太像了难怪卡梅隆会找上他。剧情一般但当年肯定还是蛮轰动。','2012-05-05 18:04:48'),(15,'蜉蝣','推荐','液态机器人的创造者叫戴森，所以脑袋就经常被轰成中空的圆形。（胡扯==','2019-02-03 16:17:03');
/*!40000 ALTER TABLE `终结者2_审判日` ENABLE KEYS */;
UNLOCK TABLES;

