/*!40000 ALTER TABLE `绿里奇迹` DISABLE KEYS */;
INSERT INTO `绿里奇迹` VALUES (1,'林||我们谈什么都像谈死！','推荐','“我累了，不想活了，真的，我不想再像孤雁一样，我不想再过没有朋友的日子，我希望有人能告诉我该何去何从，我不想再看到丑陋的人性，我不想在每日承担全世界的痛苦。”讲的是耶稣么？十字架变成了电椅。','2009-01-08 21:09:57'),(2,'鱼丸粗面','推荐','片子缺少一种关键的非现实渲染，让人感觉离奇得难以接受，但是仍然是一部好片子','2007-03-14 11:34:04'),(3,'阿吉娃娃','推荐','故事性很强的传奇宗教寓言式电影。神爱世人，而世人却不理解这份爱。人类摧毁了神迹，而神却不忍让世人背负这罪名。1.【you can\'t hide whate\'s in your heart】2.【What happens in the Mile, always stays in the Mile. 】3.【If don\'t help,don\'t tell him.Ever.】4.【awful tired life.Dog-tired】','2012-08-19 13:52:38'),(4,'燕爷','力荐','天使也怕黑暗。','2011-01-22 13:21:28'),(5,'朝暮雪','推荐','汤姆·汉克斯版《肖申克的救赎》。','2012-11-02 23:10:43'),(6,'巴喆','推荐','基督教的宣传片？！三个小时，从宗教上去阐述几个哲学命题：死刑、宗教、忏悔、善恶、宽容，人性。最后加入基督教的宣传语：来吧爱吧，人性深处，有爱就有奇迹！7.8','2011-12-24 00:08:55'),(7,'晨光荣耀','力荐','耶稣小传','2009-01-09 14:27:21'),(8,'20个小明≯','推荐','人是没法掩盖他们的恶的，即便骗的过一时但绝对骗不过一世，终有一日会败露！恶有恶报，与人为善吧…弗兰科和金真是黄金搭档，他俩的作品不会差，只是本片实在太长了，略显拖沓，可能有些难忍受，不过看起来不会让人生厌，冲突很强，一直牵着你看下去！看到了TWD里的戴尔，当时好年轻啊…','2012-08-31 15:57:26'),(9,'蛋蛋','力荐','带着满脸的眼泪和鼻涕泡儿看完的','2008-05-30 13:17:04'),(10,'汪金卫','推荐','《肖申克的救赎》导演+汤姆汉克斯。居然是一部有奇幻色彩的片子。剧本打磨得完美无瑕。演员们的演技均可圈可点，各展所长。但一本正经地讲述这样一个离奇的奇幻故事还是无法让人完全信服。宗教色彩浓厚。角色脸谱化。而且三小时篇幅太冗长，可以砍到2小时。虽然没被感动到，但依然是一部用心的佳作','2013-08-13 17:40:23'),(11,'魏神陌那','推荐','共情能力是礼物，也是惩罚。','2020-06-06 19:33:00'),(12,'完颜穆尔登格','推荐','中文名翻译成绿里神迹更好，西方信仰宗教的人是相信神迹的，黑人带来了上帝对人间的救赎，却被人间的恶毒伤害得太累。我的疑问在于，被黑人给予了长生的小老鼠和男主角，是幸运还是更久背负着人间痛苦。 人间巧合大概都不是巧合。今天早上起来，阿肥告诉我，我的兔孩子死了，之前每次世界外面旅行归来，北京的家里都有它等着我，现在我被疫情隔在爱尔兰不能回北京，快一年没见，它死掉了。它不需要感谢我养着它，我应该感谢它陪了我十年。我去了家旁边的教堂给它点蜡烛，都柏林的天总是阴沉沉的，但一束强光从马赛克窗子正好洒在我跪下的地方，我不是什么相信宗教的人，这一刻我看到了一点神迹。','2020-07-11 18:25:43'),(13,'小雨沙沙地下','推荐','影片虽长，但片中想传达出来的人生的真谛真的引人深思。很经典，值得一看。','2017-03-13 18:29:34'),(14,'私享史','推荐','忒长了……','2008-03-30 12:47:39'),(15,'德州没有巴黎','推荐','本片从剧作乃至观赏性上来说绝对都是相当不错的。但是本片和导演自己的代表作《肖申克的救赎》相比，差就差在了表意这个环节上。达拉邦特太想把自己关于宗教，死刑，人性的复杂想法融入到本片中，这就使得面面俱到却又都不够深入。相较之下，《肖申克的救赎》因其所探讨主题的纯粹性而显得更加深刻。','2015-07-05 23:05:39');
/*!40000 ALTER TABLE `绿里奇迹` ENABLE KEYS */;
UNLOCK TABLES;

