INSERT INTO `英雄本色` VALUES (1,'陌聆','推荐','Leslie这个萌娃。据说有次Leslie在电影院看午夜场，他跟盆友说：要死了，观众那麼喜欢发仔，而我却是个要抓发仔和我哥哥的警察。 第二部的时候，他开森的说：这回有人同情我了。看我演得多好！我的妻子怀孕生子时，我死佐~','2012-09-19 22:00:05'),(2,'徒然曜日','无评分','为人当如小马哥','2010-10-13 21:29:53'),(3,'反引力疯子','力荐','有几个镜头里，龙哥会发光','2010-04-05 22:09:02'),(4,'战国客','力荐','香港黑帮电影的代表作！小马哥，那是一个神的样子~~','2007-06-24 10:20:57'),(5,'趙小漁','力荐','我親愛的小馬哥，時至今日你讓我感嘆英雄遲暮更是種折磨……','2008-05-08 22:22:29'),(6,'王小邪','力荐','英雄泪短,兄弟情长','2008-02-04 00:49:46'),(7,'香水瓶','力荐','三个男人的戏，打得太精彩太经典了！ 2023.4.2 今天看了4K粤语版，这次发现“不如我们重头来过”小马哥也这么对宋子豪说。','2006-04-27 23:23:39'),(8,'失意的孩子','力荐','9.3 “《英雄本色》触及男人的父子情、兄弟情、朋友情、男女情、冤屈受害之情与报仇雪恨之情，堪称多情而善感之作。”侠肝义胆，豪情万丈，句句金言，幕幕动人，子弹芭蕾，暴力美学，义薄云天，热血沸腾。','2014-08-30 00:04:10'),(9,'Lan~die','推荐','警匪片里难得的作者电影。“你没有欠什么，我从来不会逼朋友去做不想做的事，我有我自己的原则，我不想一辈子被人踩在脚下，你以为我是臭要饭的，我等了三年，就是要等一个机会，我要争一口气，不是想证明我了不起；我是要告诉人家，我失去的东西一定要拿回来！” “我警告你，不要用枪指着我的头！”','2008-09-05 15:40:08'),(10,'圆首的秘书','力荐','节奏奇快，没有一句水词儿，实打实的95分钟。狄龙演得太好了，在弟弟和兄弟之间摇摆，经受着法律和道德的撕扯，始终处在灰色地带和生存的边缘。一部充满戏剧性但又十分优美的枪战片。周润发为角色增色太多，人物既有隐忍的一面又有超强的爆发力，狄龙出狱两人在车库见面一段的表演绝对留名影史。','2017-11-17 16:09:27'),(11,'一湄','力荐','兄弟和好的时候，哭得不行。','2009-01-11 22:53:57'),(12,'H','力荐','小时候还看不懂这片的情怀和意义 只看枪战精彩程度 更爱第二部 如今长大 回头看 浓浓的江湖兄弟情 讲义气 在那个年代盛行 如今 这世道变了~','2016-12-31 10:01:49'),(13,'哪吒男','力荐','小马，你信上不是这样说的。/这已经不是我们的江湖了。/不要叫我阿文，叫我阿sir。阿sir，我不做大哥已经很久了。','2015-08-15 18:10:30'),(14,'西楼尘','还行','拖着瘸腿在地上拾捡钞票，小马哥没了披着风衣的飒爽；戴着警徽去码头只身擒贼，宋子杰少了抱琴赴考的清澈。一夕之间，江湖还在，却只剩传说。那些枪口下的义气、刀尖上的锋芒，隐忍不说。粤语重映的银幕上，曾经的他们多潇洒。故事里的江湖天翻地覆，现实里的人生也各自寥落，唯有歌声与胶片曾经记得。','2017-11-20 11:34:38'),(15,'达不溜博士','推荐','能够把握住自己命运的人，就是神','2010-09-11 12:08:23');
/*!40000 ALTER TABLE `英雄本色` ENABLE KEYS */;
UNLOCK TABLES;

