INSERT INTO `茶馆` VALUES (1,'桃桃林林','推荐','“打一个学生，五毛现大洋”这也算认主归宗了。片子拍得很话剧腔，不过味道还是很好，演得也好，有滋有味。秦二爷最后那段自白，现在听着还是有些伤感。','2012-07-12 20:50:49'),(2,'丁一','无评分','“这年头让人高兴的事一件没有，让人见笑的事天天发生。”','2022-06-20 18:39:30'),(3,'少年 遊','力荐','“我看这大清要亡国啊”。','2010-07-21 20:40:13'),(4,'大熊猫','力荐','芸芸众生，人间百态。 经典台词：我爱咱们的国呀，可是谁爱我。','2010-06-27 02:32:04'),(5,'shininglove','推荐','“小姑娘，别这样，黑到头儿天会亮。小姑娘，别发愁，西山的泉水向东流。苦水去，甜水来，谁也不再作奴才。”','2013-09-11 22:39:12'),(6,'严箫玉','推荐','化妆太流弊……这个本子感觉还是更适合舞台表现，戏剧和电影之间真的很难无缝接轨。。','2014-09-05 21:09:12'),(7,'#瞬间收藏家#','力荐','总想做常四爷，做来做去却还是成了王利发。','2009-04-06 18:13:12'),(8,'毛毛毛读作cuì','力荐','管他什么时代，原来丑陋的现实都是一样的 ps:京味十足啊，那才叫演戏!!!看演员每一个比一个精彩，配角也不例外，和现在的国产电影相比，差距显而易见!!!','2010-06-19 17:32:23'),(9,'萌汉垚','力荐','我觉得这部作品不朽的原因是它的立意与故事的悲剧性，但最讽刺的是，创作他的人因为文革迫害投湖自尽，比他书中的角色还要悲惨。我真的要大笑三声，流下泪来。','2022-03-24 02:15:28'),(10,'Kerala','力荐','我总是以为过去的人善良单纯，但是看了老舍的作品之后，发现人们还都那样，真是八仙过海，各显神通，有些人偷奸耍滑，坏事做尽，有些人善良耿直，却没有好下场，坏人坏事时时有，而好人好事也并非无，简而言之，那个社会，活着已经不容易了，一切都慢慢来吧，油嘴滑舌，鸡贼心眼的人太多','2018-02-26 11:26:33'),(11,'胤祥','推荐','英若诚好赞，小丁宝好仗义。与原作相比基础改动还都不错（除了结尾）。这次看最萌的竟然是崔先生“我只会念经，不会干别的”。另外则是本片精华中的精华：“大清国要完！”','2012-04-04 00:52:51'),(12,'bird','力荐','以前吃不着花生米，现在能吃了，可牙嚼不动了。','2014-10-26 10:04:31'),(13,'轻河y','力荐','老舍先生怎么也想不到，最后自己竟然成了逆产。','2022-10-08 11:30:11'),(14,'Eve|Classified','力荐','结尾当年看哭我。芸芸众生有你我在那里，等着一切结束。','2015-12-22 14:10:21'),(15,'尹昭','力荐','话剧味儿还是挺浓，《茶馆》本身剧本搁在这儿就没话说了，老舍写得好啊，金句无数。三幕，三个时代，好像时局是变了，可照旧还是民生多艰。爱国者、实业家、圆滑者、顺民……都活不成，活不好。最后一幕，笑泪相加：“那帮狗男女他们可都活得有滋有味的，可干嘛不准我吃窝窝头啊！”','2018-11-18 19:30:33');
/*!40000 ALTER TABLE `茶馆` ENABLE KEYS */;
UNLOCK TABLES;

