INSERT INTO `虎口脱险` VALUES (1,'考拉','推荐','虽然不合理，但能够娱乐。','2008-05-20 21:20:51'),(2,'影志','推荐','“胜利属于我们” 没想到60年代就能产出如此纯粹的喜剧。','2019-06-20 13:06:35'),(3,'17950','力荐','娘的,这就是货真价实的喜剧片','2006-10-12 17:42:13'),(4,'艾小柯','力荐','永远看不腻的喜剧！','2006-06-23 01:20:46'),(5,'津五渡','还行','法国要有豆瓣，估计《举起手来》也能进250 。','2016-01-11 12:45:51'),(6,'嘉得乐','力荐','看过不下20遍,从小到大都喜欢的电影','2006-02-21 17:31:16'),(7,'余小岛','推荐','果然是英国和法国人拍的，德国人看到不得气死。。他们这是赤裸裸的把德国人当傻逼啊。','2013-07-21 00:36:29'),(8,'MaTown','力荐','老少皆宜，上海译制片厂献声','2009-01-12 08:30:00'),(9,'昵称被占不开心','推荐','永远看不腻的喜剧','2017-02-26 20:38:43'),(10,'犀牛','力荐','从小看过几十遍了吧，至今每看必笑，真正的好电影','2006-03-02 13:37:39'),(11,'外出偷狗','推荐','结果所有人都穿过德军制服了。','2017-07-08 23:26:30'),(12,'良夜正迢迢','推荐','在此次温馨愉快的逃亡过程中，敌我双方都无一人伤亡（真的！）','2021-09-30 19:35:25'),(13,'谋杀游戏机','推荐','经典二战喜剧，团结反法庶民群像。澡堂里的鸳鸯茶，没了头的将军蛋糕，阴差阳错敌方共枕，斗鸡眼的德国炮兵，一系列错置，啼笑皆非。《王中王》，《飞行器里的好小伙》...再加上出色的译制，味道就出来了。','2012-10-19 10:46:22'),(14,'蓝色啄木鸟','力荐','很喜欢的一部法式幽默喜剧片，里面有很多梗，“鸳鸯茶\"\"鸳鸯茶\"。重温仍然让人捧腹不止，也很怀念上译的配音！','2017-02-08 20:50:36'),(15,'眠去','力荐','果真是经典。','2007-10-19 13:05:13');
