INSERT INTO `这个杀手不太冷` VALUES (1,'沉歌','力荐','萝莉有颗御姐心，正太有个大叔身——邪恶又天真、残酷又温柔，多完美~','2007-10-14 15:39:36'),(2,'沙门','力荐','一半的魅力来自反派：Gary Oldman.','2007-08-16 10:52:43'),(3,'眠去','力荐','她对Leon说，自从遇见你后，我的胃，再也不痛了……','2007-02-10 10:52:10'),(4,'左宜右有Haak','力荐','一个杀手被一个萝莉害死的故事','2012-03-19 18:44:28'),(5,'大头绿豆','力荐','Leon的门打开，一束好象来自天堂的光照在Mathilda脸上。给他快乐，从不发问。细节和大方向都很出色，一部控制得几乎完美的电影。','2006-03-19 12:38:36'),(6,'shu','力荐','这个男人他是从儿时的动画片里走出来的，是邪恶和童真的混合体，这令我着迷。','2008-07-07 00:28:44'),(7,'酚酞','力荐','看到泪飙，世上最温情的杀手。 幸运的姑娘在12岁就遇到了真正的男人。','2012-03-10 17:23:47'),(8,'xjxiidjsns','力荐','-Is life always this hard.or is it just when you\'re a kid -Always like this.','2008-06-24 21:04:30'),(9,'Nalakuvara','力荐','或许是很多姑娘大叔控的根源。','2008-10-25 11:20:45'),(10,'Camellia','力荐','Léon： You\'re not going to lose me. You\'ve given me a taste for life. I wanna be happy. Sleep in a bed, have roots. And you\'ll never be alone again, Mathilda. Please, go now, baby, go. Calm down, go now, go.','2008-06-23 19:52:24'),(11,'Cherry','力荐','喜欢这个喝牛奶的男人','2005-07-12 17:13:10'),(12,'高歌','力荐','我到哪里找，像你这么好。','2010-05-15 16:11:16'),(13,'。光本','力荐','爱上了让雷诺。爱上了这个意大利杀手的温情。爱上了他脸部轮廓，和刚毅的线条。“人生诸多辛苦，是不是只有童年如此。”玛蒂尔达问。里昂说，“一直如此。”这样的话，击中了内心深处。','2006-10-16 02:16:04'),(14,'杜扬Seatory','推荐','我开始想要过得快乐，睡在床上，有牵挂','2006-10-25 01:38:08'),(15,'小儿勾','力荐','Here in my stomach. It\'s all warm. I always had a knot there, and now.. it\'s gone.','2007-01-16 18:57:09');
/*!40000 ALTER TABLE `这个杀手不太冷` ENABLE KEYS */;
UNLOCK TABLES;

