INSERT INTO `重庆森林` VALUES (1,'児童症×','推荐','一个人哭了，你给纸巾他就行； 　　但如果一间屋哭了，你就要做很多事情。','2009-09-17 20:27:33'),(2,'根','力荐','看旧电影最无法跨越的逻辑障碍：金城武怎么可能会被甩！梁朝伟怎么可能会被甩！这不是渎神吗！','2016-12-13 21:09:45'),(3,'老袁','力荐','重新看了一遍重庆森林。想知道金城武为什么可以连吃三十罐凤梨罐头加四份厨师沙拉薯条汉堡而不胖。因为早上六点起床跑步吗？','2016-12-28 00:37:09'),(4,'寂地','力荐','最喜欢王菲一边开着水龙头一边说因为下雨没有办法交电费.还有那个 加洲梦的音乐.','2006-01-02 15:10:17'),(5,'今天小熊不吃糖','力荐','我想和梁朝伟演的那个633谈恋爱……太帅了太帅了！！','2008-09-15 17:04:40'),(6,'所有团的团长','还行','挺想知道如果这电影不是王家卫+梁朝伟+王菲+林青霞+金城武，一样的表演、台词、镜头 ，会不会被人喷出来翔？','2013-01-19 19:25:22'),(7,'Scarrie','推荐','那时她还被叫做王靖雯,小鹿様闪烁的眼神,细痩无邪的身体,疯狂的暗恋也不过是纯真执着的本能','2010-08-15 20:17:50'),(8,'宋阿慕','推荐','这部片里的王菲和金城武都还是他们最光芒万丈的时候.','2008-02-19 15:00:00'),(9,'匹诺曹','无评分','当时没有看得太懂的一个片子','2007-01-15 14:05:28'),(10,'RoyKyo','力荐','看了28遍','2007-01-07 02:37:27'),(11,'米粒','推荐','唉！装逼文艺青年必看，从台词到镜头，掉帧什么的，哎哟~~~骚！托尼梁制服诱惑受不了啊，原来那么多文艺青年的台词都是这里来的，连周星驰那句都是。。。。- - 那个时候的王菲（还叫王靖雯）和金城武都像虾饺一样白嫩可爱。音乐好听呀。','2011-09-08 10:08:48'),(12,'乐安蓝','力荐','最喜欢的一部王家卫片子。喜欢王菲的那种“我爱你与你无关”的单纯，喜欢她把唱碟机开到最大，摇头晃脑地听着mamas&papas的《california dreaming》的样子~~','2008-03-02 15:14:39'),(13,'文泽尔','推荐','城市里的现代童话..加州住着不同的人，流泪的房子和变胖的香皂','2008-03-08 22:09:40'),(14,'冰红深蓝','推荐','王家卫代表作,描写都市生活的迷茫疏离和失恋的孤独寂寞。1.高度风格化的摄影:晃动手持+特效制造眩晕恍惚效果,鲜艳多样的色彩与布光,前景举杯慢动作+后景人群快进的镜头赞绝;2.两段无关故事,琐碎独白,肥皂毛巾玩偶;3.配乐辨识度高,[加州之梦]好听;4.过期罐头,墨镜雨衣,手绘机票,足够后现代。（8.5/10）','2015-06-26 22:51:10'),(15,'老鸡｜扶立','力荐','更喜欢后半段','2008-01-10 16:45:22');
/*!40000 ALTER TABLE `重庆森林` ENABLE KEYS */;
UNLOCK TABLES;

