INSERT INTO `雨中曲` VALUES (1,'光年‖影视歌三栖民工','推荐','老电影总是快乐得那么纯粹','2008-11-23 02:25:36'),(2,'周鱼','力荐','我曾无数次从《发条橙》、《AI》、《如果爱》、《WALLE》里看到对《雨中曲》的致敬 今日终于承认：这就是人类歌舞片的巅峰，超越《音乐之声》，秒杀一切，无与伦比。当然 刻画、节奏、布景等等有着非常多的毛病 还是搁置下来 好好看看吉恩凯利俘获美人心时的那副小样吧 这绝对是影史最珍贵的片段之一','2011-11-08 00:49:20'),(3,'○','力荐','美国歌舞片的代表作。Gene Kelly初获芳心后在雨中欢快地载歌载舞，此段情节堪称歌舞片历史上的永恒经典！我都不记得我把这段看过多少遍了。','2006-08-22 13:32:52'),(4,'同志亦凡人中文站','力荐','不只是经典的歌舞片，还有好莱坞电影工业无声变有声的历史跃进。这也许就是我对《艺术家》始终无感的原因：看过了真迹，谁会喜欢一个仿造的赝品？那样的星光，那样的雨滴，哪怕再过几十年都会一直定格在我的脑海里...','2013-06-09 17:52:13'),(5,'影志','推荐','“从此以后，我只在乎一个影迷”、“你是我的歌，春夏秋冬”…于是以后，见到这样的路灯，就想扶着灯柱起舞。','2006-02-04 06:19:12'),(6,'橘猫爱吃鱼','推荐','大雨的夜晚，与戴比·雷诺兹分别后，男主角陷入捕获芳心的无比快乐中，索性收起雨伞，在雨中载歌载舞！','2018-01-13 16:25:47'),(7,'喷子','力荐','最喜欢片头金凯利接受采访那段，讽的那叫一个犀利','2010-05-12 02:12:08'),(8,'流空破刃','推荐','几乎是最早的一批使用彩色胶片而非后期染色但又能有良好质感的彩色片。所谓的歌舞片之王，也……就那样了。','2010-07-17 21:40:27'),(9,'沉歌','力荐','永远记得他在雨中高唱“I\'m singing in the rain...... ”，一下雨就常常不由自主就哼起来。','2008-01-20 15:28:49'),(10,'胤祥','力荐','除了那个多余的”百老汇旋律“的唱段，这部片儿简直完美啊。重看时发现剧作上有一处颇具匠心，片头唐讲述自己的从艺经历时的现实与故事的反差，结构性地提示了本片最重要的有声电影/配音的剧情。（不得不说那个音画不同步的梗实在太好玩了！）','2007-01-29 23:20:59'),(11,'老阿飞—故园','力荐','经典到无话可说','2006-01-08 17:42:22'),(12,'有心打扰','力荐','虽然下着大雨，心情却不潮湿，因为有她—— 一个与彼此相爱的女子。漫步雨中，收起握在手中伞，在雨中尽情的欢唱与起舞。配乐满分，舞蹈满分。那些搞笑的舞蹈动作让人看着心情不自觉的轻松与愉悦起来。如果你伤心难过，如果你郁郁寡欢，如果你失落空虚，那么就在雨中高歌一曲吧。','2011-11-17 21:54:44'),(13,'战国客','力荐','歌舞片之王~~','2009-04-05 21:14:24'),(14,'圆首的秘书','力荐','这也太牛逼了，直接看傻了。牛逼之处不仅在于喜剧，在于歌舞，在于主配角的肢体表现力，更在于这部片子对默片衰落和明星、制片厂制度有着这么清晰的认识，对声音的出现到底如何改变表演系统、观影习惯和电影发展有着这么强烈的认知，这真的是现在人都拍不出来的！','2017-02-12 19:43:25'),(15,'popon pop','力荐','很好很好。但我讨厌荧幕的虚伪被一个女性承担，讨厌男人意淫女人启发自己而成为更完整的自己且解救女性。最终打开女性和真实帷幕的也靠三个男人。我宁愿看到女演员咄咄逼人对他们说“从今以后这是我的公司，我的命运我自己做主”。另一个层面导演很Genius，质量非常高，喜悦的革命，革命的喜悦，似乎在告诉我：世界就是这样开始的','2023-07-26 19:24:12');
/*!40000 ALTER TABLE `雨中曲` ENABLE KEYS */;
UNLOCK TABLES;

