INSERT INTO `飞屋环游记` VALUES (1,'萨萨','力荐','最后那些最无聊的事情，才是我最怀念的。','2009-07-24 23:40:51'),(2,'momo','力荐','最让我感动的是电影开头，这对夫妻志趣相投、相濡以沫，我想自己能不能找到这样的另一半呢','2016-09-10 21:25:01'),(3,'Mr.王™','力荐','有史以来最强壮的老爷爷和最轻便的房屋~一群最不靠谱的狗和一只引人发笑的怪鸟~外加一位惹人喜爱却戏份不多的老奶奶，组成了一部我大爱的好片！','2009-07-23 17:19:08'),(4,'工可每','还行','前面几分钟就让人落泪，后面却越来越不靠谱','2009-07-20 08:36:20'),(5,'昏金暗玉','力荐','从头哭到尾','2009-08-05 14:13:27'),(6,'逍遥兽','无评分','好莱坞逻辑——只有主角的梦想才是梦想，反角的梦想都是邪念。。。','2009-08-11 13:08:20'),(7,'阿北','力荐','史上第二彪悍钉子户的离奇拆迁故事。Pixar完美地成熟了。','2009-08-07 23:48:54'),(8,'后天的雨','力荐','在影片最开头对老夫妻一生的回顾无疑是最大泪点，他们过了很好很幸福的一生，当垂垂老矣，他们仍深爱着对方，就算你已不在，也要带着他们曾经共同的梦想在生命的最终冒险一把，就像小朋友不畏惧一切的好奇心，对生活对梦想，再大的年纪都不是阻碍','2016-11-03 22:28:31'),(9,'Orchid','推荐','“我总是记得那些无聊的小事情……”“感谢你给了我精彩的一生”，简单并深情着','2009-05-13 21:55:23'),(10,'汽车大师','推荐','去掉小孩，坏蛋，狗，鸟的话，这会是部完美的短片，but......; 那段夫妻蒙太奇应该是我迄今最喜欢的pixar段落了; 有一点不得不佩服pixar，拍的第一部3D就能完全摒弃滥斛噱头；而片头前那个“国内首部真人3D电影”的三分钟预告片，足以列入反面教材的经典了','2009-08-04 20:35:26'),(11,'Doublebitch','力荐','几十年的夫妻生活浓缩成几分钟那段美好死了。','2009-10-26 19:23:03'),(12,'hanahana','力荐','爱和梦想，勇气和希望','2009-08-05 09:40:24'),(13,'文泽尔','推荐','基本是儿童剧，最感人的部分一直到屋子初飞起的那一刻，之后就一直在梦游了..=。= 原本以为一切奇想不过是卡尔在再遇女孩那晚所做的一场梦，并且第二天天亮她还会来找他的…对男孩子气的艾莉的印象实在是太深了，这片要是只选取到艾莉死时，卡尔飞起气球，就是满分。皮克斯的技术没得说，因此4星','2009-08-09 14:42:05'),(14,'岚','力荐','近乎无可挑剔..','2009-08-05 10:34:11'),(15,'米粒','力荐','PIXAR总是这么perfect.原来和爱人相守一生是最大的冒险','2009-10-31 18:49:25');
