INSERT INTO `黑天鹅` VALUES (1,'XU','力荐','舞台上那段黑天鹅太惊艳了！！！！！！Natalie这牛逼演技！！！！！！','2010-12-20 17:34:07'),(2,'sabretooth','力荐','不配5星，至少20星。','2010-12-12 17:04:26'),(3,'Q。','力荐','“我感受到了，感到了……完美。”一段用走火入魔来成就的完美，亦真亦假、亦实亦幻。影片从始至终都弥漫着黑暗的色调，很惊悚，很压抑，无论配乐还是摄影都极其吸引观众。娜塔莉·波特曼颠覆以往，奉献了一场精彩的演出。★★★★★','2010-12-22 01:26:29'),(4,'城南草木生','力荐','好看到呛着人，波特曼就是一直被过于标致的容貌给拖累的公主，这是要飞起来了，看到干巴成那样五官依然标致的前公主薇诺娜赖德又出来跑龙套好心酸','2010-12-21 22:05:42'),(5,'胡子（胡续冬）','力荐','做三好学生不容易啊！','2010-12-27 22:51:32'),(6,'Lou Lou','推荐','那一颗星星是被吓掉的','2010-12-12 15:50:14'),(7,'晚晚','推荐','在离成功还差一步之遥的时候请不要丧心病狂','2010-12-04 15:14:41'),(8,'小椅子','力荐','AMAZING.','2010-12-16 12:18:02'),(9,'黄妖柒','还行','有点无聊 教育我们不要逼自己太紧','2010-12-20 12:05:47'),(10,'Hao','推荐','完美主义的确是一种失败的人格学说，直接导致走火入魔丧心病狂。Portman演得好用力，看得我心里发毛。假如她凭此片拿小金人的话，不为过。','2010-12-21 20:30:40'),(11,'Doublebitch','推荐','其实没想象中精彩，精神分裂的表现力度不太够，手法也比较陈旧，差出fight club几个档次，大半夜的愣是没让我有一丁点紧张或局促的感官反应。反倒是配乐和Natalie的精彩表演收服了我，整部电影在交响乐的烘托下活像一出慷慨悲壮的天鹅舞剧，Natalie美翻了','2010-12-22 02:41:51'),(12,'TORO VAN DARKO','力荐','电影果不其然像极了《怪房客》《冷血惊魂》，达伦更像波兰斯基上身，用各种心理暗示的镜头讲诉了这个关于人格分裂的心理惊悚故事。配乐剪辑特别是摄影自然没的说，波曼的表演更是精彩难忘，不仅让观众信服更是对角色心生怜悯。','2010-12-22 01:59:17'),(13,'影子的影子','力荐','不疯魔不成活，我得好好喘几口气才能缓过劲来。天鹅湖曾是我最抑郁时期的最爱，每一段曲子都如此熟悉，黑天鹅那段舞太惊艳，跳完后我的心跳加速了无数倍。文森卡索实在太诱惑了。一句话，性压抑要不得，得治！','2013-05-09 14:44:50'),(14,'jumbu','推荐','旧酒无味，但新瓶子很美。','2010-12-22 12:56:11'),(15,'桃桃林林','推荐','镜子用多了，想不精神分裂都难。故事基本就是天鹅湖的变奏，与《摔跤手》一样的手持摄影，却少了摔跤手的写实风，多了些超现实的感觉与舞台味。女主、摄影、配乐、女配都很有实力。波特曼，好运！','2010-12-21 22:50:18');
/*!40000 ALTER TABLE `黑天鹅` ENABLE KEYS */;
UNLOCK TABLES;

