LOCK TABLES `黑客帝国` WRITE;
/*!40000 ALTER TABLE `黑客帝国` DISABLE KEYS */;
INSERT INTO `黑客帝国` VALUES (1,'kidultcc','还行','想quote张潇雨的一条微博：“越是伟大的作品，在多年以后再体验越会感觉平平无奇。因为那些伟大的部分已经传承和渗透到无数的后来者里，成为了这个世界「默认设置」的一部分。换个角度讲，在实际接触到那个原始作品之前，你已经体验过它无数次了。” 而这段话就是2019年的我，对此片的观感。','2019-11-26 12:47:55'),(2,'米姐起飞','力荐','果真没让我失望~频频赞叹1999年人家的思维人家的意识 而咱都2012了还是爱构思古装穿越剧。。。','2012-01-20 11:44:36'),(3,'徐小花','还行','为数不多看不懂的电影','2006-08-16 17:39:10'),(4,'麻木粮姜','力荐','其中的哲学影响我的哲学道路','2008-04-15 21:49:44'),(5,'朝暮雪','力荐','有没有可能整个世界都是电脑模拟出来的，我们以及周围的一切只是电脑中的一串代码？ “你和所有人一样，生来就是奴隶，你生在一座自己感知不到的监狱” 这种猜想已经足够震撼，但《黑客帝国》的深度还不止于此，它还在这个基础上提出了新的问题： 你会选择蓝药丸还是红药丸？ 是选择美好的虚幻还是残酷的现实？ 表面上好像很好选，其实比我们想象中困难得多。 一边是未来的末日世界，被饥饿和寒冷所摧残，还要面临被机器人追杀的危险； 一边是温馨和平的年代，有蓝天白云、良辰美景，甚至还有成为成功人士的机会。 的确，所有人都知道梦境再美好也只是梦境。 但塞弗就是愿意为了区区一个梦境出卖所有人。 假如我们真的逃出矩阵，体验到现实的残酷，也许我们会做出和塞弗相同的选择。 正如当你做了美梦的时候，你宁愿继续留在梦里，不愿醒来。','2012-08-18 01:26:16'),(6,'HalloZen','力荐','黑格尔的异化理论，事物发展到一定阶段会异化出与之相对的异己，异己的发展会最终替代本体，人发明机器，最终被机器所替代。','2013-01-28 10:51:37'),(7,'本多','力荐','装逼哲学的开始','2007-07-08 18:00:38'),(8,'艾小柯','力荐','新的哲学，开创动作片之先河','2006-06-21 01:51:50'),(9,'高歌','力荐','禅宗慧能说：不是幡动，不是风动，而是心动。','2011-05-01 02:57:52'),(10,'fateface','力荐','1999年的电影，脑洞大得不止一点两点。更好玩的是，好像全世界正往那个方向走。这两天看完《未来简史》后不断想到这个电影，就复习了一遍。真是毫无违和感，一点都不像18年前的电影。','2017-03-20 20:27:10'),(11,'托尼·王大拿','力荐','对未来世界科技发展的隐忧，抑或是对当下世界权力构架的隐喻，还或是对永恒世界人类存在的思考，无论从哪个角度去观察，这部电影的前瞻性和深刻性都与其超强的娱乐性完美而和谐地共存。','2010-05-15 17:08:41'),(12,'西楼尘','还行','大脑觉得你死了，要身体有何用。意识觉得你死了，要自由有何用。失去了味觉，再多汁的牛排如同嚼蜡。失去了痛觉，再完美的母体都是坟墓。人类是让星球有意义的救世主，还是侵占土地的瘟疫。人工智能是豢养人类的病毒，还是构造乌托邦的上帝。如果可以，是该在红色药丸里苏醒，还是仍在蓝色药丸里沉睡？','2020-09-13 11:37:47'),(13,'唐小万','推荐','真是沧海桑田：那时候基努-里维斯还是清瘦小嫩肉，沃卓斯基姐弟还是沃卓斯基兄弟，诺基亚还是业界老大。','2013-07-20 22:03:09'),(14,'战国客','推荐','一部蕴含丰富哲理的科幻巨制，袁和平的动作指导将东方武学艺术推向全世界，尼奥躲子弹的镜头成为经典~~','2007-06-30 22:34:56'),(15,'亚比煞','力荐','科幻片就该这么牛逼，有点思想好不好，不要整天就知道打来打去','2009-09-07 09:28:08');
/*!40000 ALTER TABLE `黑客帝国` ENABLE KEYS */;
UNLOCK TABLES;

